/*
	VIOC_air_support_server.sqf - agregado por tools/vio_build.py (parche air_support; copia configurada, no es del autor
	de la mision). Fuente: work/v6_build/air_support/.

	Servidor de "PEDIR: Apoyo aereo (A-10 / Ghostrider)": CUALQUIER jugador de oeste o este pide, pagando con SUS fondos,
	  - A-10 (CAS): un avion de ataque de su bando aparece a 3 km del blanco, hace UNA pasada en picado sobre el punto
	    marcado (canon, cohetes, bombas guiadas o canon + cohetes, segun lo que lleve el avion) y se va: se borra a 3 km
	    detras del blanco. La pasada copia la de la funcion de BI BIS_fnc_moduleCAS (modulo "Apoyo aereo" de Zeus: 3000 m,
	    1000 m de altura, 400 km/h, setVelocityTransformation, fireAtTarget sobre un blanco laser durante 3 s), pero hecha
	    aqui porque el modulo no sirve con los A-10 de los mods: con el CUP (CUP_B_A10_DYN_USA) el canon, las bombas y los
	    misiles tienen cursor "EmptyCursor" y BIS_fnc_itemType no los reconoce (el modulo no encuentra armas), y con el RHS
	    (RHS_A10) en modo misiles dispararia los AIM-9 y el pod ECM; ademas el modulo deja un blanco laser sin borrar.
	    Clases: oeste RHS_A10 (RHS como mod principal) o CUP_B_A10_DYN_USA; este RHS_Su25SM_vvs o CUP_O_Su25_Dyn_RU.
	  - Ghostrider (canonero AC-130J, que NO existe en los mods): un C-130J de su bando (RHS_C130J o CUP_B_C130J_USMC)
	    con tripulacion IA da circulos (LOITER CIRCLE_L) de VIOC_ASS_GS_R m a VIOC_ASS_GS_ALT m sobre el blanco y, mientras
	    esta vivo y en orbita, este script dispara proyectiles reales hacia el blanco: 105 mm HE (CUP_Sh_105_HE, el del
	    obus M119 de CUP) cada 6-10 s y rafagas de 30 mm HE (B_30mm_HE_Tracer_Red/Green) cada 3-5 s, creados a unos
	    cientos de metros del impacto sobre la linea avion-blanco (o en vertical) con velocidad hacia el, dispersion 12-20 m.
	    Apunta a enemigos a menos de VIOC_ASS_GS_ZONE m del punto marcado (vehiculos para el 105, infanteria para el 30) o
	    al punto. Nunca dispara si hay tropas propias a menos de VIOC_ASS_DANGER m del punto de impacto (fuego en pausa).
	    El jugador puede cambiar el blanco (dentro del circulo de la orbita) con la accion "GHOSTRIDER: nuevo blanco".
	    Se le puede derribar: si cae, el siguiente Ghostrider del bando tarda VIOC_GUNSHIP_LOST_COOLDOWN min (30).
	  - Topes: 1 A-10 y 1 Ghostrider activos por bando; esperas por bando (VIOC_CAS_COOLDOWN, VIOC_GUNSHIP_COOLDOWN desde
	    que termina, VIOC_GUNSHIP_LOST_COOLDOWN si lo derriban); presupuesto de IA de perf_cleanup (VIOC_PERF_AI_MAX /
	    VIOC_PERF_AI_COUNT); VIOC_CA_fnc_banned (contemporary_assets) en las clases; cobro atomico dentro de isNil.
	  - Aviones y grupos marcados: VIOC_KEEP = true (perf_cleanup no los toca) y vioc_specops = true (airfields no les
	    da regreso a base ni servicio, ai_transport no los usa). Al terminar se borran avion, tripulacion y grupo; si los
	    derriban, los restos quedan para el recolector de la mision (VIOC_KEEP = false) y la tripulacion viva se borra
	    cuando no hay jugadores cerca.
	Solo servidor. El cliente (panel del mapa) esta en VIOC_air_support.sqf.
	Parametros de lobby: VIOC_AIR_SUPPORT, VIOC_CAS_PRICE, VIOC_CAS_COOLDOWN, VIOC_GUNSHIP_PRICE, VIOC_GUNSHIP_DURATION,
	VIOC_GUNSHIP_COOLDOWN, VIOC_GUNSHIP_LOST_COOLDOWN.
	Consola (servidor; en partida alojada vale "Ejecucion local"):
	    hint (call VIOC_AS_fnc_status);                              aviones activos, clases y esperas
	    ["cas", screenToWorld [0.5,0.5], 0] call VIOC_AS_fnc_force;  A-10 gratis donde miras (0 canon, 1 cohetes, 2 bombas, 3 mixto)
	    ["gs", screenToWorld [0.5,0.5]] call VIOC_AS_fnc_force;      Ghostrider gratis donde miras
	    [west] call VIOC_AS_fnc_forceEnd;                            el Ghostrider de ese bando termina ya
	    call VIOC_AS_fnc_resetCD;                                    borra las esperas
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_ASS_STARTED") exitWith {};
VIOC_ASS_STARTED = true;

//--- Parametros de lobby (en "Un jugador" la mision no los carga: valen los de por defecto).
VIOC_AS_fnc_param = {
	params ["_name", "_def", "_min", "_max"];
	private _v = missionNamespace getVariable [_name, _def];
	if !(_v isEqualType 0) then {_v = _def};
	((round _v) max _min) min _max
};
VIOC_ASS_MODE = ["VIOC_AIR_SUPPORT", 1, 0, 1] call VIOC_AS_fnc_param;
VIOC_ASS_CAS_PRICE = ["VIOC_CAS_PRICE", 6000, 0, 1000000] call VIOC_AS_fnc_param;
VIOC_ASS_CAS_CD = (["VIOC_CAS_COOLDOWN", 10, 0, 120] call VIOC_AS_fnc_param) * 60;
VIOC_ASS_GS_PRICE = ["VIOC_GUNSHIP_PRICE", 12000, 0, 1000000] call VIOC_AS_fnc_param;
VIOC_ASS_GS_LIFE = (["VIOC_GUNSHIP_DURATION", 5, 1, 30] call VIOC_AS_fnc_param) * 60;
VIOC_ASS_GS_CD = (["VIOC_GUNSHIP_COOLDOWN", 15, 0, 120] call VIOC_AS_fnc_param) * 60;
VIOC_ASS_GS_CD_LOST = (["VIOC_GUNSHIP_LOST_COOLDOWN", 30, 0, 180] call VIOC_AS_fnc_param) * 60;

//--- Ajustes
VIOC_ASS_DANGER = 75;		//--- m: ni pedir ni disparar con tropas propias a menos de esto del impacto
VIOC_ASS_DANGER_BOMB = 100;	//--- m: idem para las bombas guiadas del A-10
VIOC_ASS_CAS_DIS = 3000;	//--- m: el A-10 aparece a esta distancia del blanco (como BIS_fnc_moduleCAS)
VIOC_ASS_CAS_ALT = 1000;	//--- m: y a esta altura sobre el blanco (picado de 18 grados, como el modulo)
VIOC_ASS_CAS_SPEED = 400 / 3.6;	//--- m/s en el picado (como el modulo)
VIOC_ASS_CAS_FIRE = 3;		//--- s de fuego (como el modulo)
VIOC_ASS_GS_R = 1800;		//--- m: radio de la orbita del Ghostrider (y radio maximo para cambiar el blanco)
VIOC_ASS_GS_ALT = 2500;		//--- m sobre el suelo
VIOC_ASS_GS_SPAWN = 4500;	//--- m del blanco donde aparece (del lado de lo propio mas cercano)
VIOC_ASS_GS_ZONE = 150;		//--- m alrededor del blanco donde busca enemigos
VIOC_ASS_GS_T105 = [6, 4];	//--- 105 mm: cada 6 s + hasta 4 s al azar
VIOC_ASS_GS_T30 = [3, 2];	//--- 30 mm: una rafaga cada 3 s + hasta 2 s al azar
VIOC_ASS_GS_BURST = 8;		//--- disparos por rafaga de 30 mm
VIOC_ASS_GS_SPREAD = [12, 10, 8];	//--- dispersion (m): 105 mm; centro de la rafaga de 30 mm; cada disparo de la rafaga
VIOC_ASS_GS_ORBIT_T = 300;	//--- s maximos para llegar a la orbita (si no, se cancela y se devuelve el dinero)
VIOC_ASS_GONE_R = 2500;		//--- al irse, se borra cuando no hay jugadores a menos de esto
VIOC_ASS_GONE_T = 240;		//--- o a los 4 min de irse
VIOC_ASS_DEBUG = false;

//--- Estado
VIOC_ASS_ACTIVE = [];		//--- HashMaps: kind ("cas"/"gs"), side, uid, player, plane, grp, cls, price, center, aim, state...
VIOC_ASS_CD = [];			//--- [kind, side, time hasta el que espera, motivo ("done"/"lost")]
VIOC_ASS_CLASS = [["", ""], ["", ""]];	//--- [[A-10 oeste, A-10 este], [Ghostrider oeste, Ghostrider este]]
VIOC_ASS_MODES = [[false, false, false, false], [false, false, false, false]];	//--- modos del A-10 por bando: canon, cohetes, bombas guiadas, mixto
VIOC_ASS_W105 = "";
VIOC_ASS_W30 = ["", ""];
VIOC_ASS_SEQ = 0;			//--- numero de cada pedido (para sacarlo del registro)

VIOC_AS_fnc_log = {diag_log format ["[VIOC air_support] %1", _this]};

//--- Identificador del jugador (UID; en "Un jugador" puede venir vacio).
VIOC_AS_fnc_uid = {
	params ["_p"];
	private _u = getPlayerUID _p;
	if (_u == "") then {_u = "local"};
	_u
};

//--- "12:30 min" o "45 s"
VIOC_AS_fnc_time = {
	params ["_s"];
	_s = round _s;
	if (_s < 60) exitWith {format ["%1 s", _s]};
	private _sec = _s mod 60;
	format ["%1:%2%3 min", floor (_s / 60), ["", "0"] select (_sec < 10), _sec]
};

//--- Espera que le queda a un bando para un tipo ("cas"/"gs"): [segundos, motivo].
VIOC_AS_fnc_cdLeft = {
	params ["_kind", "_side"];
	private _i = VIOC_ASS_CD findIf {((_x select 0) == _kind) && {(_x select 1) == _side}};
	if (_i < 0) exitWith {[0, ""]};
	private _c = VIOC_ASS_CD select _i;
	[((_c select 2) - time) max 0, _c select 3]
};
VIOC_AS_fnc_setCD = {
	params ["_kind", "_side", "_secs", "_why"];
	VIOC_ASS_CD = VIOC_ASS_CD select {!(((_x select 0) == _kind) && {(_x select 1) == _side})};
	if (_secs > 0) then {VIOC_ASS_CD pushBack [_kind, _side, time + _secs, _why]};
};
VIOC_AS_fnc_resetCD = {VIOC_ASS_CD = []; "esperas borradas"};

//--- Presupuesto de IA de perf_cleanup (VIOC_PERF_AI_MAX > 0): true si caben _n unidades mas.
VIOC_AS_fnc_perfOk = {
	params [["_n", 0]];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", 0];
	if (!(_max isEqualType 0) || {_max <= 0}) exitWith {true};
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", 0];
	if !(_cnt isEqualType 0) exitWith {true};
	(_cnt + _n) <= _max
};

//--- true si la politica de contemporary_assets quita la clase (false si ese parche no esta).
VIOC_AS_fnc_banned = {
	params ["_c"];
	if (isNil "VIOC_CA_fnc_banned") exitWith {false};
	private _r = [_c] call VIOC_CA_fnc_banned;
	(!isNil "_r") && {_r isEqualTo true}
};

//--- Nacion principal del bando: "US", "RU", "CW" (Guerra Fria / 1968) o "" y si el mod principal es RHS.
VIOC_AS_fnc_nation = {
	params ["_side"];
	private _sog = missionNamespace getVariable ["CTI_SOG_DLC", -1];
	if (!isNil "CTI_US_SIDE" && {_sog isEqualType 0} && {_sog > 1}) exitWith {["CW", false]};
	private _nat = "";
	private _mod = -1;
	private _mn = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], []];
	if (!isNil "CTI_US_SIDE" && {_mn isEqualType []} && {count _mn > 1}) then {
		private _n = _mn select 0;
		_mod = _mn select 1;
		if (_n isEqualTo (missionNamespace getVariable ["CTI_US_ID", 2])) then {_nat = "US"};
		if (_n isEqualTo (missionNamespace getVariable ["CTI_SOV_ID", 3])) then {_nat = "RU"};
		if ((_n isEqualTo (missionNamespace getVariable ["CTI_BW_ID", 0])) || {_n isEqualTo (missionNamespace getVariable ["CTI_NVA_ID", 1])}) then {_nat = "CW"};
	};
	if (_nat == "" && {!isNil "CTI_US_SIDE"}) then {
		private _sid = _side call CTI_CO_FNC_GetSideID;
		if ((missionNamespace getVariable ["CTI_US_SIDE", -1]) isEqualTo _sid) then {_nat = "US"} else {
			if ((missionNamespace getVariable ["CTI_SOV_SIDE", -1]) isEqualTo _sid) then {_nat = "RU"};
		};
	};
	if (_nat == "") then {_nat = ["RU", "US"] select (_side == west)};
	[_nat, _mod isEqualTo (missionNamespace getVariable ["CTI_RHS_ID", 5])]
};

//--- Clases candidatas: _kind 0 = A-10 (CAS), 1 = Ghostrider. Rusia no tiene canonero en los mods (ni Il-76 ni An-12).
VIOC_AS_fnc_candidates = {
	params ["_side", "_kind"];
	([_side] call VIOC_AS_fnc_nation) params ["_nat", "_rhs"];
	switch (true) do {
		case (_nat == "CW"): {[]};
		case (_nat == "US" && {_kind == 0}): {if (_rhs) then {["RHS_A10", "CUP_B_A10_DYN_USA", "B_Plane_CAS_01_dynamicLoadout_F"]} else {["CUP_B_A10_DYN_USA", "RHS_A10", "B_Plane_CAS_01_dynamicLoadout_F"]}};
		case (_nat == "US" && {_kind == 1}): {if (_rhs) then {["RHS_C130J", "CUP_B_C130J_USMC"]} else {["CUP_B_C130J_USMC", "RHS_C130J"]}};
		case (_nat == "RU" && {_kind == 0}): {if (_rhs) then {["RHS_Su25SM_vvs", "CUP_O_Su25_Dyn_RU", "O_Plane_CAS_02_dynamicLoadout_F"]} else {["CUP_O_Su25_Dyn_RU", "RHS_Su25SM_vvs", "O_Plane_CAS_02_dynamicLoadout_F"]}};
		default {[]};
	}
};

//--- Primera candidata que existe, es publica (scope 2), es un avion y no esta prohibida; las del mismo lado primero.
VIOC_AS_fnc_pickClass = {
	params ["_side", "_kind"];
	private _sn = [east, west, resistance] find _side;
	private _ok = [];
	{
		private _cfg = configFile >> "CfgVehicles" >> _x;
		if (isClass _cfg && {getNumber (_cfg >> "scope") >= 2} && {(configName _cfg) isKindOf "Plane"} && {!([configName _cfg] call VIOC_AS_fnc_banned)}) then {
			_ok pushBack [configName _cfg, (getNumber (_cfg >> "side")) == _sn];
		};
	} forEach ([_side, _kind] call VIOC_AS_fnc_candidates);
	private _same = _ok select {_x select 1};
	if (count _same > 0) exitWith {(_same select 0) select 0};
	if (count _ok > 0) exitWith {(_ok select 0) select 0};
	""
};

//--- Tipo de un arma de avion segun su clase y la municion de su cargador: "gun" (CannonCore / MGunCore), "rocket"
//--- (RocketPods sin guia), "lgb" (bomba con laserLock), "bomb", "missile" (aire-tierra) o "" (bengalas, laser, aire-aire).
//--- Comprobado con las configs reales (evidence_classes.txt): las bengalas heredan de MGunCore (se quitan por la municion
//--- shotCM), los AIM-9 / R-60 / R-73 heredan de RocketPods (se quitan por airLock 2) y la FAB-250 de RHS hereda de una
//--- bomba guiada pero tiene laserLock 0.
VIOC_AS_fnc_wkind = {
	params ["_w", "_mag"];
	private _ammo = getText (configFile >> "CfgMagazines" >> _mag >> "ammo");
	if (_w == "" || {_ammo == ""} || {!isClass (configFile >> "CfgAmmo" >> _ammo)}) exitWith {""};
	private _ca = configFile >> "CfgAmmo";
	private _cw = configFile >> "CfgWeapons";
	private _ac = _ca >> _ammo;
	if ((toLower getText (_ac >> "simulation")) in ["shotcm", "laserdesignate", "shotilluminating", "shotsmoke", "shotsmokex"]) exitWith {""};
	if (_ammo isKindOf ["BombCore", _ca]) exitWith {if (getNumber (_ac >> "laserLock") == 1) then {"lgb"} else {"bomb"}};
	if (getNumber (_ac >> "airLock") >= 2) exitWith {""};
	if (_w isKindOf ["RocketPods", _cw]) exitWith {if ((getNumber (_ac >> "irLock") == 0) && {getNumber (_ac >> "laserLock") == 0}) then {"rocket"} else {"missile"}};
	if ((_w isKindOf ["CannonCore", _cw]) || {_w isKindOf ["MGunCore", _cw]}) exitWith {"gun"};
	if ((_w isKindOf ["MissileLauncher", _cw]) && {getNumber (_ac >> "hit") > 0}) exitWith {"missile"};
	""
};

//--- Armas del piloto de una clase segun la config: [[arma, tipo], ...] (armas fijas + pilones por defecto).
VIOC_AS_fnc_cfgWeapons = {
	params ["_cls"];
	private _cfg = configFile >> "CfgVehicles" >> _cls;
	private _res = [];
	private _mags = (getArray (_cfg >> "magazines")) apply {toLower _x};
	{
		private _w = _x;
		private _wm = (getArray (configFile >> "CfgWeapons" >> _w >> "magazines")) select {(toLower _x) in _mags};
		if (count _wm > 0) then {
			private _k = [_w, _wm select 0] call VIOC_AS_fnc_wkind;
			if (_k != "") then {_res pushBackUnique [configName (configFile >> "CfgWeapons" >> _w), _k]};
		};
	} forEach (getArray (_cfg >> "weapons"));
	{
		private _m = getText (_x >> "attachment");
		if (_m != "") then {
			private _w = getText (configFile >> "CfgMagazines" >> _m >> "pylonWeapon");
			if (_w != "" && {isClass (configFile >> "CfgWeapons" >> _w)}) then {
				private _k = [_w, _m] call VIOC_AS_fnc_wkind;
				if (_k != "") then {_res pushBackUnique [configName (configFile >> "CfgWeapons" >> _w), _k]};
			};
		};
	} forEach (configProperties [_cfg >> "Components" >> "TransportPylonsComponent" >> "Pylons", "isClass _x"]);
	_res
};

//--- Tipos de arma de cada modo del A-10: 0 canon, 1 cohetes, 2 bombas guiadas, 3 mixto (canon + cohetes).
VIOC_ASS_MODE_KINDS = [["gun"], ["rocket"], ["lgb"], ["gun", "rocket"]];
VIOC_ASS_MODE_NAMES = ["canon", "cohetes", "bombas guiadas", "canon + cohetes"];
VIOC_AS_fnc_modesOf = {
	params ["_cls"];
	if (_cls == "") exitWith {[false, false, false, false]};
	private _k = ([_cls] call VIOC_AS_fnc_cfgWeapons) apply {_x select 1};
	[("gun" in _k), ("rocket" in _k), ("lgb" in _k), ("gun" in _k) && {"rocket" in _k}]
};

//--- Lo propio mas cercano al blanco: HQ, estructuras, aerodromos propios (airfields) o el marcador de reaparicion.
VIOC_AS_fnc_home = {
	params ["_side", "_target"];
	private _c = [];
	private _hq = _side call CTI_CO_FNC_GetSideHQ;
	if (!isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq}) then {_c pushBack (getPosATL _hq)};
	private _sts = _side call CTI_CO_FNC_GetSideStructures;
	if (!isNil "_sts" && {_sts isEqualType []}) then {
		{if (_x isEqualType objNull && {!isNull _x}) then {_c pushBack (getPosATL _x)}} forEach _sts;
	};
	private _sid = _side call CTI_CO_FNC_GetSideID;
	private _tab = missionNamespace getVariable ["VIOC_AF_TABLE", []];
	if (_tab isEqualType []) then {
		{
			if ((_x isEqualType createHashMap) && {(_x getOrDefault ["owner", -9]) isEqualTo _sid}) then {
				private _p = _x getOrDefault ["ils", []];
				if (_p isEqualType [] && {count _p > 1}) then {_c pushBack _p};
			};
		} forEach _tab;
	};
	if (count _c == 0) then {
		private _m = format ["CTI_%1Respawn", _side];
		if (markerType _m != "") then {_c pushBack (markerPos _m)};
	};
	private _best = [];
	private _bd = 1e10;
	{
		private _d = _x distance2D _target;
		if (_d < _bd) then {_bd = _d; _best = _x};
	} forEach _c;
	_best
};

//--- true si hay tropas propias (de _side o aliadas; hombres a pie o vehiculos con tripulacion viva) a menos de _r de _pos.
VIOC_AS_fnc_friendlyNear = {
	params ["_pos", "_side", "_r"];
	private _p = [_pos select 0, _pos select 1, 0];
	((_p nearEntities [["CAManBase", "LandVehicle", "StaticWeapon", "Ship", "Air"], _r]) findIf {
		alive _x && {
			private _s = if (_x isKindOf "CAManBase") then {side group _x} else {if (({alive _x} count (crew _x)) > 0) then {side _x} else {civilian}};
			(_s in [west, east, resistance]) && {(_side getFriend _s) >= 0.6}
		}
	}) >= 0
};

//--- true si hay algun jugador humano vivo a menos de _dist (2D) del objeto o posicion.
VIOC_AS_fnc_playersNear = {
	params ["_obj", "_dist"];
	private _pl = allPlayers select {!(_x isKindOf "HeadlessClient_F")};
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	(_pl findIf {alive _x && {(_x distance2D _obj) < _dist}}) >= 0
};

//--- Jugador conectado con ese UID (o objNull).
VIOC_AS_fnc_findPlayer = {
	params ["_uid"];
	private _c = allPlayers select {([_x] call VIOC_AS_fnc_uid) == _uid};
	if (count _c == 0 && {!isMultiplayer} && {hasInterface} && {!isNull player}) then {_c = [player]};
	if (count _c > 0) then {_c select 0} else {objNull}
};

//--- Mensajes al jugador (por objeto o UID) y al bando.
VIOC_AS_fnc_reply = {
	params ["_player", "_ok", "_text", ["_data", []]];
	if (isNull _player) exitWith {};
	[_ok, _text, _data] remoteExecCall ["VIOC_ASR_fnc_reply", _player];
};
VIOC_AS_fnc_note = {
	params ["_uid", "_text", ["_data", []]];
	private _p = [_uid] call VIOC_AS_fnc_findPlayer;
	if (isNull _p) exitWith {};
	[_text, _data] remoteExecCall ["VIOC_ASR_fnc_note", _p];
};
VIOC_AS_fnc_sideSay = {
	params ["_side", "_text"];
	[format ["[Apoyo aereo] %1", _text]] remoteExec ["systemChat", _side];
};

//--- Ruta del picado del A-10: el avion viene desde lo propio (o el rumbo que mejor libre el terreno), cae 1000 m en
//--- 3000 m hasta el blanco y sale por el otro lado. Devuelve [rumbo desde el blanco hasta el punto de salida, holgura m].
VIOC_AS_fnc_casRoute = {
	params ["_side", "_tgt"];
	private _home = [_side, _tgt] call VIOC_AS_fnc_home;
	private _base = if ((count _home > 1) && {(_home distance2D _tgt) > 50}) then {_tgt getDir _home} else {random 360};
	private _gz = (getTerrainHeightASL _tgt) max 0;
	private _best = -1;
	private _bestC = -1e9;
	{
		private _from = (_base + _x + 360) mod 360;
		private _sp = _tgt getPos [VIOC_ASS_CAS_DIS, _from];
		private _c = 1e9;
		if (((_sp select 0) < 100) || {(_sp select 1) < 100} || {(_sp select 0) > (worldSize - 100)} || {(_sp select 1) > (worldSize - 100)}) then {_c = -1e8};
		for "_i" from 2 to 10 do {
			private _f = _i / 10;
			private _p = _tgt getPos [VIOC_ASS_CAS_DIS * _f, _from];
			_c = _c min (((_gz + VIOC_ASS_CAS_ALT * _f) - ((getTerrainHeightASL _p) max 0)) - 60);
		};
		for "_i" from 1 to 5 do {
			private _d = _i * 500;
			private _p = _tgt getPos [_d, _from + 180];
			_c = _c min ((_gz + 150 + 0.25 * _d) - ((getTerrainHeightASL _p) max 0));
		};
		if (_c > _bestC) then {_bestC = _c; _best = _from};
		if (_c >= 0) exitWith {};
	} forEach [0, 30, -30, 60, -60, 90, -90, 120, -120, 150, -150, 180];
	[_best, _bestC]
};

//--- Crea el avion volando con su tripulacion IA del bando. Devuelve [avion, grupo] o el motivo (texto).
VIOC_AS_fnc_spawnPlane = {
	params ["_side", "_cls", "_posASL", "_dir", "_speed"];
	private _pl = createVehicle [_cls, [_posASL select 0, _posASL select 1, 500], [], 0, "FLY"];
	if (isNull _pl) exitWith {"no se pudo crear el avion"};
	_pl setDir _dir;
	_pl setPosASL _posASL;
	_pl setVelocityModelSpace [0, _speed, 0];
	private _cg = createVehicleCrew _pl;
	if (isNil "_cg" || {!(_cg isEqualType grpNull)} || {isNull _cg}) then {_cg = group (driver _pl)};
	private _crew = crew _pl;
	if (count _crew == 0 || {isNull (driver _pl)}) exitWith {{deleteVehicle _x} forEach _crew; deleteVehicle _pl; "el avion no recibio tripulacion IA"};
	if ((side _cg) != _side) then {
		private _old = _cg;
		_cg = createGroup [_side, true];
		if (!isNull _cg) then {
			_crew joinSilent _cg;
			if ((count units _old) == 0) then {deleteGroup _old};
		};
	};
	if (isNull _cg || {(side _cg) != _side}) exitWith {
		{deleteVehicle _x} forEach (crew _pl);
		deleteVehicle _pl;
		"no se pudo dar el avion a tu bando"
	};
	_cg setBehaviour "CARELESS";
	_cg setCombatMode "BLUE";
	_cg allowFleeing 0;
	_cg setVariable ["vioc_specops", true, true];
	{_x setCaptive false; _x allowFleeing 0} forEach (crew _pl);
	_pl setCaptive false;
	_pl setFuel 1;
	_pl lock 2;
	_pl setVariable ["VIOC_KEEP", true, true];
	_pl setVariable ["vioc_specops", true, true];
	_pl addEventHandler ["Fired", {
		params ["_unit", "_weapon"];
		if (((_unit getVariable ["vioc_as_wl", []]) findIf {_x == _weapon}) >= 0) then {_unit setVariable ["vioc_as_shots", (_unit getVariable ["vioc_as_shots", 0]) + 1]};
	}];
	if (!isNil "VIOC_ZEUS" && {VIOC_ZEUS isEqualType objNull} && {!isNull VIOC_ZEUS}) then {VIOC_ZEUS addCuratorEditableObjects [[_pl], true]};
	[_pl, _cg]
};

//--- Borra la tripulacion que quede viva (p. ej. eyectada) cuando no hay jugadores cerca (o a los 10 min) y el grupo.
VIOC_AS_fnc_crewCleanup = {
	params ["_cg"];
	private _t = time + 600;
	waitUntil {
		sleep 10;
		isNull _cg || {({alive _x} count (units _cg)) == 0} || {time > _t} || {!([leader _cg, 1000] call VIOC_AS_fnc_playersNear)}
	};
	if (isNull _cg) exitWith {};
	{if (!isNull _x && {vehicle _x == _x}) then {deleteVehicle _x}} forEach (units _cg);
	if (({alive _x} count (units _cg)) == 0) then {deleteGroup _cg};
};

//--- Borra un avion (con su tripulacion y grupo) cuando ya no hay jugadores cerca o pasa el tiempo; si cae: restos al recolector.
//--- Devuelve true si se perdio (derribado) mientras se iba.
VIOC_AS_fnc_planeGone = {
	params ["_pl", "_cg", "_far", "_tmax"];
	private _t0 = time;
	waitUntil {
		sleep 3;
		isNull _pl || {!alive _pl} || {(time - _t0) > _tmax} || {((time - _t0) > 10) && {(_pl distance2D _far) < 1500 || {!([_pl, VIOC_ASS_GONE_R] call VIOC_AS_fnc_playersNear)}}}
	};
	private _lost = !isNull _pl && {!alive _pl};
	if (_lost) then {
		_pl setVariable ["VIOC_KEEP", false, true];
		[_cg] spawn VIOC_AS_fnc_crewCleanup;
	} else {
		if (!isNull _pl) then {
			{deleteVehicle _x} forEach (crew _pl);
			deleteVehicle _pl;
		};
		{if (!isNull _x) then {deleteVehicle _x}} forEach (units _cg);
		if (!isNull _cg) then {deleteGroup _cg};
	};
	_lost
};

//--- Disparo del A-10 durante la pasada (como BIS_fnc_moduleCAS: fireAtTarget cada 0,1 s durante 3 s; bombas: 2).
VIOC_AS_fnc_casFire = {
	params ["_pl", "_weapons", "_lt", "_mode"];
	private _drv = driver _pl;
	if (_mode == 2) exitWith {
		for "_i" from 1 to 2 do {
			{_drv fireAtTarget [_lt, _x]} forEach _weapons;
			_pl setVariable ["vioc_as_fp", _i / 2];
			sleep 0.6;
		};
		sleep 1;
	};
	private _t = time + VIOC_ASS_CAS_FIRE;
	waitUntil {
		sleep 0.1;
		{_drv fireAtTarget [_lt, _x]} forEach _weapons;
		_pl setVariable ["vioc_as_fp", (1 - ((_t - time) / VIOC_ASS_CAS_FIRE)) max 0 min 1];
		time > _t || {isNull _pl} || {!alive _drv}
	};
	sleep 1;
};

//--- Mision de un A-10 (con spawn): pasada en picado, disparo, salida y borrado. _e = HashMap del registro.
VIOC_AS_fnc_casRun = {
	params ["_e"];
	private _pl = _e get "plane";
	private _cg = _e get "grp";
	private _side = _e get "side";
	private _uid = _e get "uid";
	private _pos = _e get "tgt";
	private _from = _e get "from";
	private _mode = _e get "mode";
	private _pname = _e get "pname";
	private _dn = _e get "dname";
	private _dis = VIOC_ASS_CAS_DIS;
	private _alt = VIOC_ASS_CAS_ALT;
	private _duration = ([0, 0] distance [_dis, _alt]) / VIOC_ASS_CAS_SPEED;
	private _planePos = getPosASL _pl;
	private _vectorDir = _planePos vectorFromTo _pos;
	private _velocity = _vectorDir vectorMultiply VIOC_ASS_CAS_SPEED;
	private _exit = _pos getPos [_dis, _from + 180];
	//--- armas del avion de los tipos del modo (fijas y de pilones)
	private _kinds = VIOC_ASS_MODE_KINDS select _mode;
	private _have = (_pl weaponsTurret [-1]) + (weapons _pl);
	private _weapons = [];
	{
		_x params ["_w", "_k"];
		if ((_k in _kinds) && {(_have findIf {_x == _w}) >= 0}) then {_weapons pushBackUnique _w};
	} forEach ([typeOf _pl] call VIOC_AS_fnc_cfgWeapons);
	_pl setVariable ["vioc_as_wl", _weapons];	//--- el evento Fired cuenta solo los disparos de estas armas (no las bengalas)
	//--- como el modulo: orden de salida, IA sin moverse ni buscar blancos, descuidada
	_pl move _exit;
	_pl disableAI "MOVE";
	_pl disableAI "TARGET";
	_pl disableAI "AUTOTARGET";
	_pl setCombatMode "BLUE";
	_pl setVectorDir _vectorDir;
	[_pl, -90 + atan (_dis / _alt), 0] call BIS_fnc_setPitchBank;
	private _vectorUp = vectorUp _pl;
	//--- blanco laser: el del bando que ya este a menos de 250 m (un jugador designando) o uno nuevo que se borra despues
	private _ltType = if ((_side getFriend west) > 0.6) then {"LaserTargetW"} else {"LaserTargetE"};
	private _posAGL = ASLToAGL _pos;
	private _lt = (_posAGL nearEntities [_ltType, 250]) param [0, objNull];
	private _ltOwn = false;
	if (isNull _lt) then {
		_lt = createVehicle [_ltType, _posAGL, [], 0, "NONE"];
		_ltOwn = true;
	};
	private _danger = [VIOC_ASS_DANGER, VIOC_ASS_DANGER_BOMB] select (_mode == 2);
	private _offset = [0, 10, 0, 0] select _mode;
	private _time = time;
	private _fired = false;
	private _abort = "";
	private _h = scriptNull;
	_pl setVariable ["vioc_as_fp", 0];
	waitUntil {
		sleep 0.01;
		if (!isNull _pl && {alive _pl}) then {
			private _fp = _pl getVariable ["vioc_as_fp", 0];
			_pl setVelocityTransformation [
				_planePos, [_pos select 0, _pos select 1, (_pos select 2) + _offset + _fp * 12],
				_velocity, _velocity,
				_vectorDir, _vectorDir,
				_vectorUp, _vectorUp,
				(time - _time) / _duration
			];
			_pl setVelocity (velocity _pl);
			if (!_fired && {((getPosASL _pl) distance _pos) < 1000}) then {
				_fired = true;
				if ([_pos, _side, _danger] call VIOC_AS_fnc_friendlyNear) then {_abort = "friendly"} else {
					if (count _weapons == 0) then {_abort = "noweapon"} else {
						_pl reveal _lt;
						(driver _pl) doWatch _lt;
						(driver _pl) doTarget _lt;
						_h = [_pl, _weapons, _lt, _mode] spawn VIOC_AS_fnc_casFire;
					};
				};
			};
		};
		_abort != "" || {isNull _pl} || {!alive _pl} || {isNull (driver _pl)} || {_fired && {scriptDone _h}} || {((time - _time) / _duration) > 0.9}
	};
	private _lost = isNull _pl || {!alive _pl} || {isNull (driver _pl)} || {!alive (driver _pl)};
	private _shots = if (isNull _pl) then {0} else {_pl getVariable ["vioc_as_shots", 0]};
	if (!_lost) then {
		_pl setVelocity (velocity _pl);
		_pl flyInHeight _alt;
		if (_mode != 2 && {"CMFlareLauncher" in (weapons _pl)}) then {
			for "_i" from 0 to 1 do {
				(driver _pl) forceWeaponFire ["CMFlareLauncher", "Burst"];
				sleep 1.1;
			};
		};
	};
	if (_ltOwn) then {[_lt] spawn {params ["_o"]; sleep 25; deleteVehicle _o}};
	//--- fuera del registro; espera, devolucion y avisos
	VIOC_ASS_ACTIVE = VIOC_ASS_ACTIVE select {(_x get "id") != (_e get "id")};
	private _price = _e get "price";
	private _refund = false;
	private _msg = "";
	switch (true) do {
		case (_abort == "friendly" && {!_lost}): {
			_refund = true;
			_msg = format ["%1 aborto la pasada: hay tropas propias a menos de %2 m del blanco. No disparo; se te devolvieron los %3.", _dn, _danger, _price];
		};
		case (_lost && {_shots > 0}): {_msg = format ["%1 ataco el blanco, pero fue derribado.", _dn]};
		case (_lost): {_msg = format ["%1 fue derribado antes de atacar. No hay devolucion.", _dn]};
		case (_shots == 0): {
			_refund = true;
			_msg = format ["%1 no pudo disparar (%2); se te devolvieron los %3.", _dn, if (_abort == "noweapon") then {"no lleva armas de ese tipo"} else {"sin disparos"}, _price];
		};
		default {_msg = format ["%1: pasada de %2 completada sobre la cuadricula %3; regresa a base.", _dn, VIOC_ASS_MODE_NAMES select _mode, mapGridPosition _pos]};
	};
	if (_refund) then {
		if (_price > 0 && {!(_e getOrDefault ["free", false])}) then {[_e get "pgrp", _side, _price] call CTI_CO_FNC_ChangeFunds};
	} else {
		["cas", _side, VIOC_ASS_CAS_CD, "done"] call VIOC_AS_fnc_setCD;
	};
	[_uid, _msg, ["cas", if (_refund) then {0} else {VIOC_ASS_CAS_CD}]] call VIOC_AS_fnc_note;
	if (_lost) then {[_side, format ["El %1 pedido por %2 fue derribado.", _dn, _pname]] call VIOC_AS_fnc_sideSay};
	format ["A-10 de %1 (%2): fin, disparos %3, abort '%4', perdido %5", _pname, _side, _shots, _abort, _lost] call VIOC_AS_fnc_log;
	if (_lost) exitWith {
		if (!isNull _pl) then {_pl setVariable ["VIOC_KEEP", false, true]};
		[_cg] spawn VIOC_AS_fnc_crewCleanup;
	};
	//--- salida: como el modulo, se borra a 3 km del blanco (o cuando nadie lo ve, o a los 90 s)
	private _t0 = time;
	waitUntil {
		sleep 1;
		isNull _pl || {!alive _pl} || {(_pl distance2D _pos) > _dis} || {(time - _t0) > 90}
	};
	if (!isNull _pl && {!alive _pl}) exitWith {
		_pl setVariable ["VIOC_KEEP", false, true];
		[_cg] spawn VIOC_AS_fnc_crewCleanup;
	};
	[_pl, _cg, _exit, 120] call VIOC_AS_fnc_planeGone;
};

//--- Proyectil del Ghostrider: nace a _dist m del impacto sobre la linea avion-impacto (o en vertical si el terreno
//--- estorba) con velocidad _speed hacia el impacto. Credito de las bajas para el avion (setShotParents).
VIOC_AS_fnc_gsShot = {
	params ["_pl", "_imp", "_ammo", "_speed", "_dist"];
	private _src = getPosASL _pl;
	private _sp = _imp vectorAdd ((_imp vectorFromTo _src) vectorMultiply _dist);
	if (((_sp select 2) < (((getTerrainHeightASL _sp) max 0) + 25)) || {terrainIntersectASL [_sp, _imp vectorAdd [0, 0, 2]]}) then {
		_sp = _imp vectorAdd [0, 0, _dist];
	};
	private _vel = (_sp vectorFromTo _imp) vectorMultiply _speed;
	private _pr = createVehicle [_ammo, ASLToAGL _sp, [], 0, "NONE"];
	if (isNull _pr) exitWith {false};
	_pr setPosASL _sp;
	_pr setVectorDir _vel;
	_pr setVelocity _vel;
	if (!isNull (driver _pl)) then {_pr setShotParents [_pl, driver _pl]};
	true
};

//--- Punto al azar en un disco de radio _r alrededor de _p (al nivel del suelo o del mar).
VIOC_AS_fnc_disk = {
	params ["_p", "_r"];
	private _d = _r * sqrt (random 1);
	private _a = random 360;
	private _q = [(_p select 0) + _d * sin _a, (_p select 1) + _d * cos _a, 0];
	_q set [2, (getTerrainHeightASL _q) max 0];
	_q
};

//--- Blancos del Ghostrider cerca del punto marcado: [vehiculos enemigos con tripulacion, hombres enemigos a pie].
VIOC_AS_fnc_gsTargets = {
	params ["_aim", "_side"];
	private _veh = [];
	private _inf = [];
	{
		if (alive _x) then {
			if (_x isKindOf "CAManBase") then {
				private _s = side group _x;
				if ((_s in [west, east, resistance]) && {(_side getFriend _s) < 0.6}) then {_inf pushBack _x};
			} else {
				if (({alive _x} count (crew _x)) > 0) then {
					private _s = side _x;
					if ((_s in [west, east, resistance]) && {(_side getFriend _s) < 0.6}) then {_veh pushBack _x};
				};
			};
		};
	} forEach ([_aim select 0, _aim select 1, 0] nearEntities [["CAManBase", "LandVehicle", "StaticWeapon", "Ship"], VIOC_ASS_GS_ZONE]);
	[_veh, _inf]
};

//--- Un disparo (105) o una rafaga (30) del Ghostrider. Devuelve "ok", "friendly" (todo bloqueado por tropas propias).
VIOC_AS_fnc_gsFire = {
	params ["_e", "_gun"];
	private _pl = _e get "plane";
	private _side = _e get "side";
	private _aim = _e get "aim";
	([_aim, _side] call VIOC_AS_fnc_gsTargets) params ["_veh", "_inf"];
	private _first = [_inf, _veh] select (_gun == "105");
	private _second = [_veh, _inf] select (_gun == "105");
	private _pts = [];
	if (count _first > 0) then {_pts pushBack (getPosASL (selectRandom _first))};
	if (count _first > 1) then {_pts pushBack (getPosASL (selectRandom _first))};
	if (count _second > 0) then {_pts pushBack (getPosASL (selectRandom _second))};
	_pts pushBack [_aim select 0, _aim select 1, (getTerrainHeightASL _aim) max 0];
	private _i = _pts findIf {!([_x, _side, VIOC_ASS_DANGER] call VIOC_AS_fnc_friendlyNear)};
	if (_i < 0) exitWith {"friendly"};
	private _p = _pts select _i;
	if (_gun == "105") then {
		[_pl, [_p, VIOC_ASS_GS_SPREAD select 0] call VIOC_AS_fnc_disk, VIOC_ASS_W105, 320, 350] call VIOC_AS_fnc_gsShot;
		_e set ["n105", (_e get "n105") + 1];
	} else {
		private _c = [_p, VIOC_ASS_GS_SPREAD select 1] call VIOC_AS_fnc_disk;
		private _w = VIOC_ASS_W30 select ([0, 1] select (_side != west));
		for "_k" from 1 to VIOC_ASS_GS_BURST do {
			if (!alive _pl) exitWith {};
			[_pl, [_c, VIOC_ASS_GS_SPREAD select 2] call VIOC_AS_fnc_disk, _w, 900, 250] call VIOC_AS_fnc_gsShot;
			sleep 0.09;
		};
		_e set ["n30", (_e get "n30") + 1];
	};
	"ok"
};

//--- Mision de un Ghostrider (con spawn): llega, da circulos y dispara VIOC_ASS_GS_LIFE s, se va y se borra.
VIOC_AS_fnc_gsRun = {
	params ["_e"];
	private _pl = _e get "plane";
	private _cg = _e get "grp";
	private _side = _e get "side";
	private _uid = _e get "uid";
	private _pname = _e get "pname";
	private _dn = "Ghostrider";
	private _t0 = time;
	private _inOrbit = false;
	private _fireEnd = 1e10;
	private _why = "";
	private _n105 = 0;
	private _n30 = 0;
	private _pauseMsg = -1e9;
	private _warned = false;
	while {true} do {
		sleep 0.5;
		if (isNull _pl || {!alive _pl} || {isNull (driver _pl)} || {!alive (driver _pl)}) exitWith {_why = "lost"};
		if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {_why = "over"};
		if (_pl getVariable ["vioc_as_end", false]) exitWith {_why = "forced"};
		if (((damage _pl) > 0.6) || {!canMove _pl}) exitWith {_why = "damaged"};
		if (_inOrbit && {time >= _fireEnd}) exitWith {_why = "time"};
		if (!_inOrbit && {(time - _t0) > VIOC_ASS_GS_ORBIT_T}) exitWith {_why = "noorbit"};
		if ((fuel _pl) < 0.3) then {_pl setFuel 1};
		private _center = _e get "center";
		private _orbitOk = ((_pl distance2D _center) < (VIOC_ASS_GS_R + 900)) && {((getPosATL _pl) select 2) > 800};
		if (!_inOrbit && {_orbitOk}) then {
			_inOrbit = true;
			_fireEnd = time + VIOC_ASS_GS_LIFE;
			_e set ["state", "fire"];
			_e set ["fireEnd", _fireEnd];
			_e set ["next105", time + 3];
			_e set ["next30", time + 5];
			[_uid, format ["Ghostrider en orbita sobre la cuadricula %1: abre fuego durante %2 min.", mapGridPosition _center, round (VIOC_ASS_GS_LIFE / 60)]] call VIOC_AS_fnc_note;
		};
		if (_inOrbit && {!_warned} && {(_fireEnd - time) <= 60}) then {
			_warned = true;
			[_uid, "Ghostrider: queda 1 minuto de fuego."] call VIOC_AS_fnc_note;
		};
		if (_inOrbit && {_orbitOk}) then {
			private _blocked = false;
			if (time >= (_e get "next105")) then {
				_e set ["next105", time + (VIOC_ASS_GS_T105 select 0) + random (VIOC_ASS_GS_T105 select 1)];
				if (([_e, "105"] call VIOC_AS_fnc_gsFire) == "friendly") then {_blocked = true};
			};
			if (time >= (_e get "next30")) then {
				_e set ["next30", time + (VIOC_ASS_GS_T30 select 0) + random (VIOC_ASS_GS_T30 select 1)];
				if (([_e, "30"] call VIOC_AS_fnc_gsFire) == "friendly") then {_blocked = true};
			};
			if (_blocked && {(time - _pauseMsg) > 45}) then {
				_pauseMsg = time;
				[_uid, format ["Ghostrider: fuego en pausa, hay tropas propias a menos de %1 m del blanco. Marca otro blanco (accion GHOSTRIDER: nuevo blanco) o aleja a tus tropas.", VIOC_ASS_DANGER]] call VIOC_AS_fnc_note;
			};
		};
	};
	_n105 = _e get "n105";
	_n30 = _e get "n30";
	VIOC_ASS_ACTIVE = VIOC_ASS_ACTIVE select {(_x get "id") != (_e get "id")};
	private _price = _e get "price";
	private _free = _e getOrDefault ["free", false];
	private _cd = VIOC_ASS_GS_CD;
	private _msg = "";
	switch (_why) do {
		case "lost": {
			_cd = VIOC_ASS_GS_CD_LOST;
			_msg = format ["El Ghostrider fue derribado (%1 disparos de 105 mm y %2 rafagas de 30 mm). El proximo estara disponible en %3.", _n105, _n30, [_cd] call VIOC_AS_fnc_time];
		};
		case "time": {_msg = format ["Ghostrider: fuego terminado (%1 disparos de 105 mm y %2 rafagas de 30 mm); regresa a base.", _n105, _n30]};
		case "damaged": {_msg = "El Ghostrider esta muy danado: deja de disparar y regresa a base."};
		case "forced": {_msg = "El Ghostrider regresa a base (terminado desde la consola)."};
		case "noorbit": {
			_cd = 0;
			_msg = format ["El Ghostrider no llego a la orbita: se cancela y se te devolvieron los %1.", _price];
			if (_price > 0 && {!_free}) then {[_e get "pgrp", _side, _price] call CTI_CO_FNC_ChangeFunds};
		};
		default {_cd = 0; _msg = "El Ghostrider regresa a base (la partida termino)."};
	};
	["gs", _side, _cd, ["done", "lost"] select (_why == "lost")] call VIOC_AS_fnc_setCD;
	[_uid, _msg, ["gs", _cd]] call VIOC_AS_fnc_note;
	if (_why == "lost") then {[_side, format ["El Ghostrider pedido por %1 fue derribado; habra otro en %2.", _pname, [_cd] call VIOC_AS_fnc_time]] call VIOC_AS_fnc_sideSay};
	format ["Ghostrider de %1 (%2): fin '%3', 105 mm %4, rafagas 30 mm %5", _pname, _side, _why, _n105, _n30] call VIOC_AS_fnc_log;
	if (_why == "lost") exitWith {
		if (!isNull _pl) then {_pl setVariable ["VIOC_KEEP", false, true]};
		[_cg] spawn VIOC_AS_fnc_crewCleanup;
	};
	//--- regreso: punto lejano hacia lo propio y se borra cuando nadie lo ve; si cae en el camino cuenta como derribado
	private _center = _e get "center";
	private _home = [_side, _center] call VIOC_AS_fnc_home;
	private _hd = if ((count _home > 1) && {(_home distance2D _center) > 50}) then {_center getDir _home} else {_center getDir _pl};
	private _away = _center getPos [9000, _hd];
	private _wp = _cg addWaypoint [_away, 0];
	_wp setWaypointType "MOVE";
	_wp setWaypointBehaviour "CARELESS";
	_wp setWaypointCombatMode "BLUE";
	_wp setWaypointSpeed "FULL";
	_cg setCurrentWaypoint _wp;
	if ([_pl, _cg, _away, VIOC_ASS_GONE_T] call VIOC_AS_fnc_planeGone) then {
		["gs", _side, VIOC_ASS_GS_CD_LOST, "lost"] call VIOC_AS_fnc_setCD;
		[_uid, format ["El Ghostrider fue derribado mientras regresaba. El proximo estara disponible en %1.", [VIOC_ASS_GS_CD_LOST] call VIOC_AS_fnc_time], ["gs", VIOC_ASS_GS_CD_LOST]] call VIOC_AS_fnc_note;
		[_side, format ["El Ghostrider pedido por %1 fue derribado mientras regresaba; habra otro en %2.", _pname, [VIOC_ASS_GS_CD_LOST] call VIOC_AS_fnc_time]] call VIOC_AS_fnc_sideSay;
	};
};

//--- Quita del registro lo que quedo colgado (si el hilo de una mision muriera).
VIOC_AS_fnc_prune = {
	VIOC_ASS_ACTIVE = VIOC_ASS_ACTIVE select {
		private _p = _x getOrDefault ["plane", objNull];
		((_x get "state") == "spawning" && {time < ((_x get "t0") + 60)}) || {!isNull _p && {alive _p}} || {time < ((_x get "t0") + 120)}
	};
};

//--- Pedido de un jugador (llega con remoteExecCall desde su cliente). Comprueba el remitente y responde.
//--- [jugador, tipo ("cas"/"gs"), posicion, modo del A-10 (0-3), precio que vio (-1 = no mirar)]
VIOC_AS_fnc_request = {
	params [["_player", objNull, [objNull]], ["_kind", "", [""]], ["_pos", [], [[]]], ["_mode", 0, [0]], ["_seen", -1, [0]]];
	if (!isServer || {isNull _player}) exitWith {};
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != (owner _player)}) exitWith {format ["pedido ignorado: la maquina %1 no controla a %2", _ro, name _player] call VIOC_AS_fnc_log};
	private _r = [_player, _kind, _pos, _mode, _seen, false] call VIOC_AS_fnc_requestDo;
	if (_r != "ok") then {
		[_player, false, _r, [_kind]] call VIOC_AS_fnc_reply;
		format ["pedido %1 de %2 rechazado: %3", _kind, name _player, _r] call VIOC_AS_fnc_log;
	};
};

//--- Valida, cobra y lanza. _free = true (consola): sin cobro, sin espera ni tope. Devuelve "ok" o el motivo.
VIOC_AS_fnc_requestDo = {
	params ["_player", "_kind", "_pos", "_mode", "_seen", "_free"];
	if (VIOC_ASS_MODE <= 0) exitWith {"el apoyo aereo esta desactivado en el lobby"};
	if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {"la partida termino"};
	if (!alive _player) exitWith {"tienes que estar vivo"};
	private _side = side group _player;
	private _si = [west, east] find _side;
	if (_si < 0) exitWith {"tu bando no puede pedir apoyo aereo"};
	private _ki = ["cas", "gs"] find _kind;
	if (_ki < 0) exitWith {"tipo de apoyo no valido"};
	private _cls = (VIOC_ASS_CLASS select _ki) select _si;
	if (_cls == "") exitWith {if (_ki == 0) then {"tu bando no tiene avion de ataque (A-10) en este escenario"} else {"tu bando no tiene canonero (Ghostrider) en este escenario"}};
	private _dn = if (_ki == 1) then {"Ghostrider"} else {getText (configFile >> "CfgVehicles" >> _cls >> "displayName")};
	if (_ki == 0 && {(_mode < 0) || {_mode > 3} || {!(((VIOC_ASS_MODES select _si) select _mode) isEqualTo true)}}) exitWith {format ["el %1 no lleva armas para ese tipo de ataque", _dn]};
	call VIOC_AS_fnc_prune;
	if (!_free && {(VIOC_ASS_ACTIVE findIf {((_x get "kind") == _kind) && {(_x get "side") == _side}}) >= 0}) exitWith {format ["tu bando ya tiene un %1 en el aire (uno por bando)", _dn]};
	private _cd = [_kind, _side] call VIOC_AS_fnc_cdLeft;
	if (!_free && {(_cd select 0) > 0}) exitWith {format ["todavia no: el proximo %1 estara disponible en %2%3", _dn, [_cd select 0] call VIOC_AS_fnc_time, if ((_cd select 1) == "lost") then {" (el anterior fue derribado)"} else {""}]};
	private _ncrew = [_cls, false] call BIS_fnc_crewCount;
	if (isNil "_ncrew" || {!(_ncrew isEqualType 0)}) then {_ncrew = 2};
	if (!_free && {!([_ncrew max 1] call VIOC_AS_fnc_perfOk)}) exitWith {"ahora hay demasiada IA en la partida (presupuesto VIOC_PERF_AI_MAX); prueba mas tarde"};
	if ((count _pos) < 2 || {!((_pos select 0) isEqualType 0)} || {!((_pos select 1) isEqualType 0)}) exitWith {"posicion no valida"};
	_pos = [_pos select 0, _pos select 1, 0];
	if ((_pos select 0) < 0 || {(_pos select 1) < 0} || {(_pos select 0) > worldSize} || {(_pos select 1) > worldSize}) exitWith {"el blanco esta fuera del mapa"};
	private _danger = if (_ki == 0 && {_mode == 2}) then {VIOC_ASS_DANGER_BOMB} else {VIOC_ASS_DANGER};
	if ([_pos, _side, _danger] call VIOC_AS_fnc_friendlyNear) exitWith {format ["hay tropas propias (o tu) a menos de %1 m del blanco: marca un punto mas lejos", _danger]};
	private _route = [];
	if (_ki == 0) then {_route = [_side, _pos] call VIOC_AS_fnc_casRoute};
	if (_ki == 0 && {(_route select 1) < 0}) exitWith {"el terreno no deja una pasada de ataque segura hacia ese punto (montanas): marca otro"};
	private _price = if (_free) then {0} else {[VIOC_ASS_CAS_PRICE, VIOC_ASS_GS_PRICE] select _ki};
	if (!_free && {_seen >= 0} && {_price > (_seen + 1)}) exitWith {format ["el precio cambio: ahora cuesta %1 (viste %2); vuelve a pedirlo", _price, _seen]};
	//--- cobro y reserva del puesto (sin interrupciones entre mirar y descontar)
	private _grp = group _player;
	private _uid = [_player] call VIOC_AS_fnc_uid;
	private _e = createHashMapFromArray [["kind", _kind], ["side", _side], ["uid", _uid], ["player", _player], ["pgrp", _grp], ["pname", name _player],
		["cls", _cls], ["dname", _dn], ["price", _price], ["free", _free], ["mode", _mode], ["state", "spawning"], ["t0", time], ["n105", 0], ["n30", 0]];
	private _paid = false;
	private _busy = false;
	private _funds = 0;
	isNil {
		if (!_free && {(VIOC_ASS_ACTIVE findIf {((_x get "kind") == _kind) && {(_x get "side") == _side}}) >= 0}) then {_busy = true} else {
			_funds = [_grp, _side] call CTI_CO_FNC_GetFunds;
			if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
			if (_funds >= _price) then {
				if (_price > 0) then {[_grp, _side, -_price] call CTI_CO_FNC_ChangeFunds};
				_paid = true;
				VIOC_ASS_SEQ = VIOC_ASS_SEQ + 1;
				_e set ["id", VIOC_ASS_SEQ];
				VIOC_ASS_ACTIVE pushBack _e;
			};
		};
	};
	if (_busy) exitWith {format ["tu bando ya tiene un %1 en el aire (uno por bando)", _dn]};
	if (!_paid) exitWith {format ["no te alcanza: cuesta %1 y tienes %2", _price, round _funds]};
	//--- creacion del avion
	private _sp = "";
	if (_ki == 0) then {
		private _from = _route select 0;
		private _tgt = [_pos select 0, _pos select 1, (getTerrainHeightASL _pos) max 0];
		private _p2 = _tgt getPos [VIOC_ASS_CAS_DIS, _from];
		_e set ["tgt", _tgt];
		_e set ["from", _from];
		_e set ["center", _tgt];
		_e set ["aim", _tgt];
		_sp = [_side, _cls, [_p2 select 0, _p2 select 1, (_tgt select 2) + VIOC_ASS_CAS_ALT], _from + 180, VIOC_ASS_CAS_SPEED] call VIOC_AS_fnc_spawnPlane;
	} else {
		private _home = [_side, _pos] call VIOC_AS_fnc_home;
		private _dir = if ((count _home > 1) && {(_home distance2D _pos) > 50}) then {_pos getDir _home} else {random 360};
		private _p2 = _pos getPos [VIOC_ASS_GS_SPAWN, _dir];
		_p2 = [((_p2 select 0) max 200) min (worldSize - 200), ((_p2 select 1) max 200) min (worldSize - 200), 0];
		private _alt = (((getTerrainHeightASL _p2) max (getTerrainHeightASL _pos)) max 0) + VIOC_ASS_GS_ALT;
		_e set ["center", _pos];
		_e set ["aim", _pos];
		_sp = [_side, _cls, [_p2 select 0, _p2 select 1, _alt], _p2 getDir _pos, 120] call VIOC_AS_fnc_spawnPlane;
	};
	if (_sp isEqualType "") exitWith {
		VIOC_ASS_ACTIVE = VIOC_ASS_ACTIVE select {(_x get "id") != (_e get "id")};
		if (_price > 0) then {[_grp, _side, _price] call CTI_CO_FNC_ChangeFunds};
		format ["%1 (se te devolvieron los %2)", _sp, _price]
	};
	_sp params ["_pl", "_cg"];
	_pl setVariable ["vioc_as_uid", _uid, true];
	_pl setVariable ["vioc_as_kind", _kind, true];
	_e set ["plane", _pl];
	_e set ["grp", _cg];
	_e set ["state", "fly"];
	private _who = name _player;
	if (_ki == 0) then {
		[_player, true, format ["%1 en camino: pasada de %2 sobre la cuadricula %3 en unos 25 s. Costo %4.", _dn, VIOC_ASS_MODE_NAMES select _mode, mapGridPosition _pos, _price], ["cas", _pl, _pos, VIOC_ASS_CAS_CD]] call VIOC_AS_fnc_reply;
		[_side, format ["%1 pidio un %2 (%3) sobre la cuadricula %4.", _who, _dn, VIOC_ASS_MODE_NAMES select _mode, mapGridPosition _pos]] call VIOC_AS_fnc_sideSay;
		format ["A-10 de %1 (%2): %3 modo %4 sobre %5, costo %6", _who, _side, _cls, _mode, mapGridPosition _pos, _price] call VIOC_AS_fnc_log;
		[_e] spawn VIOC_AS_fnc_casRun;
	} else {
		_pl flyInHeight VIOC_ASS_GS_ALT;
		private _asl = ((getTerrainHeightASL _pos) max 0) + VIOC_ASS_GS_ALT;
		_pl flyInHeightASL [_asl, _asl, _asl];
		private _wp = _cg addWaypoint [_pos, 0];
		_wp setWaypointType "LOITER";
		_wp setWaypointLoiterType "CIRCLE_L";
		_wp setWaypointLoiterRadius VIOC_ASS_GS_R;
		_wp setWaypointBehaviour "CARELESS";
		_wp setWaypointCombatMode "BLUE";
		_wp setWaypointSpeed "NORMAL";
		_cg setCurrentWaypoint _wp;
		[_player, true, format ["Ghostrider (%1) en camino a la cuadricula %2: llega en 1-2 min, da circulos de %3 m a %4 m de altura y dispara %5 min (105 mm y 30 mm). Costo %6.", getText (configFile >> "CfgVehicles" >> _cls >> "displayName"), mapGridPosition _pos, VIOC_ASS_GS_R, VIOC_ASS_GS_ALT, round (VIOC_ASS_GS_LIFE / 60), _price], ["gs", _pl, _pos, VIOC_ASS_GS_R]] call VIOC_AS_fnc_reply;
		[_side, format ["%1 pidio el Ghostrider sobre la cuadricula %2.", _who, mapGridPosition _pos]] call VIOC_AS_fnc_sideSay;
		format ["Ghostrider de %1 (%2): %3 sobre %4, costo %5, %6 s de fuego", _who, _side, _cls, mapGridPosition _pos, _price, VIOC_ASS_GS_LIFE] call VIOC_AS_fnc_log;
		[_e] spawn VIOC_AS_fnc_gsRun;
	};
	"ok"
};

//--- Nuevo blanco del Ghostrider (accion del cliente). Solo el que lo pidio y dentro del circulo de la orbita.
VIOC_AS_fnc_retarget = {
	params [["_player", objNull, [objNull]], ["_pos", [], [[]]]];
	if (!isServer || {isNull _player}) exitWith {};
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != (owner _player)}) exitWith {};
	private _uid = [_player] call VIOC_AS_fnc_uid;
	private _i = VIOC_ASS_ACTIVE findIf {((_x get "kind") == "gs") && {(_x get "uid") == _uid}};
	if (_i < 0) exitWith {[_player, false, "no tienes un Ghostrider en el aire", ["re"]] call VIOC_AS_fnc_reply};
	private _e = VIOC_ASS_ACTIVE select _i;
	if ((count _pos) < 2 || {!((_pos select 0) isEqualType 0)} || {!((_pos select 1) isEqualType 0)}) exitWith {[_player, false, "posicion no valida", ["re"]] call VIOC_AS_fnc_reply};
	_pos = [_pos select 0, _pos select 1, 0];
	private _c = _e get "center";
	if ((_pos distance2D _c) > VIOC_ASS_GS_R) exitWith {[_player, false, format ["ese punto esta fuera de la orbita (a %1 m del centro; maximo %2 m)", round (_pos distance2D _c), VIOC_ASS_GS_R], ["re"]] call VIOC_AS_fnc_reply};
	_e set ["aim", _pos];
	private _warn = if ([_pos, _e get "side", VIOC_ASS_DANGER] call VIOC_AS_fnc_friendlyNear) then {format [" Ojo: hay tropas propias a menos de %1 m; no disparara ahi mientras sigan.", VIOC_ASS_DANGER]} else {""};
	[_player, true, format ["Ghostrider: nuevo blanco en la cuadricula %1.%2", mapGridPosition _pos, _warn], ["re", _e getOrDefault ["plane", objNull], _c, VIOC_ASS_GS_R, _pos]] call VIOC_AS_fnc_reply;
};

//--- Estado para el panel del cliente: [A-10 activo, espera s, Ghostrider activo, espera s, motivo, tu Ghostrider, centro, blanco].
VIOC_AS_fnc_query = {
	params [["_player", objNull, [objNull]]];
	if (!isServer || {isNull _player}) exitWith {};
	private _side = side group _player;
	private _uid = [_player] call VIOC_AS_fnc_uid;
	call VIOC_AS_fnc_prune;
	private _cas = (VIOC_ASS_ACTIVE findIf {((_x get "kind") == "cas") && {(_x get "side") == _side}}) >= 0;
	private _gi = VIOC_ASS_ACTIVE findIf {((_x get "kind") == "gs") && {(_x get "side") == _side}};
	private _cc = ["cas", _side] call VIOC_AS_fnc_cdLeft;
	private _gc = ["gs", _side] call VIOC_AS_fnc_cdLeft;
	private _mine = objNull;
	private _cen = [];
	private _aim = [];
	if (_gi >= 0) then {
		private _e = VIOC_ASS_ACTIVE select _gi;
		if ((_e get "uid") == _uid) then {_mine = _e getOrDefault ["plane", objNull]; _cen = _e get "center"; _aim = _e get "aim"};
	};
	[[_cas, _cc select 0, _gi >= 0, _gc select 0, _gc select 1, _mine, _cen, _aim]] remoteExecCall ["VIOC_ASR_fnc_status", _player];
};

//--- Consola: apoyo gratis para el jugador local (sin espera ni tope). ["cas", pos, modo] o ["gs", pos].
VIOC_AS_fnc_force = {
	params [["_kind", "cas", [""]], ["_pos", [], [[]]], ["_mode", -1, [0]]];
	if (!hasInterface || {isNull player}) exitWith {"sin jugador local"};
	private _si = [west, east] find (side group player);
	if (_kind == "cas" && {_mode < 0} && {_si >= 0}) then {_mode = (VIOC_ASS_MODES select _si) findIf {_x}};
	if (count _pos < 2) then {_pos = screenToWorld [0.5, 0.5]};
	private _r = [player, _kind, _pos, _mode max 0, -1, true] call VIOC_AS_fnc_requestDo;
	if (_r != "ok") then {[player, false, _r, [_kind]] call VIOC_AS_fnc_reply};
	_r
};

//--- Consola: el Ghostrider del bando termina ya (se va a base).
VIOC_AS_fnc_forceEnd = {
	params [["_side", west]];
	{
		if (((_x get "kind") == "gs") && {(_x get "side") == _side} && {!isNull (_x getOrDefault ["plane", objNull])}) then {(_x get "plane") setVariable ["vioc_as_end", true]};
	} forEach VIOC_ASS_ACTIVE;
};

//--- Consola: estado.
VIOC_AS_fnc_status = {
	private _l = [format ["Apoyo aereo: modo %1. A-10: oeste %2 / este %3 (modos %4 / %5), precio %6, espera %7 min. Ghostrider: oeste %8 / este %9, precio %10, %11 min de fuego, espera %12 min (derribado %13 min). Municion: %14, %15.",
		VIOC_ASS_MODE, (VIOC_ASS_CLASS select 0) select 0, (VIOC_ASS_CLASS select 0) select 1, VIOC_ASS_MODES select 0, VIOC_ASS_MODES select 1, VIOC_ASS_CAS_PRICE, round (VIOC_ASS_CAS_CD / 60),
		(VIOC_ASS_CLASS select 1) select 0, (VIOC_ASS_CLASS select 1) select 1, VIOC_ASS_GS_PRICE, round (VIOC_ASS_GS_LIFE / 60), round (VIOC_ASS_GS_CD / 60), round (VIOC_ASS_GS_CD_LOST / 60), VIOC_ASS_W105, VIOC_ASS_W30]];
	{
		private _p = _x getOrDefault ["plane", objNull];
		_l pushBack format ["- %1 de %2 (%3): %4, %5, cuadricula %6, 105 mm %7, rafagas %8", _x get "kind", _x get "pname", _x get "side", _x get "state", if (alive _p) then {format ["%1 m de altura", round ((getPosATL _p) select 2)]} else {"sin avion"}, mapGridPosition (_x getOrDefault ["aim", [0, 0, 0]]), _x get "n105", _x get "n30"];
	} forEach VIOC_ASS_ACTIVE;
	{_l pushBack format ["- espera %1 %2: %3 s (%4)", _x select 0, _x select 1, round (((_x select 2) - time) max 0), _x select 3]} forEach VIOC_ASS_CD;
	_l joinString "\n"
};

//--- Para los clientes: clases, modos y precios (una vez, cuando la mision esta lista).
[] spawn {
	waitUntil {sleep 2; !isNil "CTI_Init_Server"};
	VIOC_ASS_CLASS = [0, 1] apply {
		private _k = _x;
		[west, east] apply {if (VIOC_ASS_MODE > 0) then {[_x, _k] call VIOC_AS_fnc_pickClass} else {""}}
	};
	VIOC_ASS_MODES = (VIOC_ASS_CLASS select 0) apply {[_x] call VIOC_AS_fnc_modesOf};
	//--- un A-10 sin ningun modo util no se ofrece
	{
		if (((VIOC_ASS_MODES select _forEachIndex) findIf {_x}) < 0) then {(VIOC_ASS_CLASS select 0) set [_forEachIndex, ""]};
	} forEach (VIOC_ASS_CLASS select 0);
	VIOC_ASS_W105 = (["CUP_Sh_105_HE", "Sh_120mm_HE_Tracer_Red", "Sh_155mm_AMOS"] select {isClass (configFile >> "CfgAmmo" >> _x)}) param [0, "Sh_155mm_AMOS"];
	VIOC_ASS_W30 = [(["B_30mm_HE_Tracer_Red", "B_30mm_HE"] select {isClass (configFile >> "CfgAmmo" >> _x)}) param [0, "B_30mm_HE"], (["B_30mm_HE_Tracer_Green", "B_30mm_HE"] select {isClass (configFile >> "CfgAmmo" >> _x)}) param [0, "B_30mm_HE"]];
	private _dn = VIOC_ASS_CLASS apply {_x apply {if (_x == "") then {""} else {getText (configFile >> "CfgVehicles" >> _x >> "displayName")}}};
	VIOC_AS_CFG = [VIOC_ASS_MODE > 0, VIOC_ASS_CLASS, _dn, VIOC_ASS_MODES, VIOC_ASS_CAS_PRICE, VIOC_ASS_GS_PRICE, VIOC_ASS_GS_LIFE, VIOC_ASS_CAS_CD, VIOC_ASS_GS_CD, VIOC_ASS_GS_CD_LOST, VIOC_ASS_GS_R, VIOC_ASS_DANGER, VIOC_ASS_GS_ALT, VIOC_ASS_DANGER_BOMB];
	publicVariable "VIOC_AS_CFG";
	format ["activo: modo %1, A-10 %2 (modos %3), Ghostrider %4, 105 mm %5, 30 mm %6, precios %7 / %8", VIOC_ASS_MODE, VIOC_ASS_CLASS select 0, VIOC_ASS_MODES, VIOC_ASS_CLASS select 1, VIOC_ASS_W105, VIOC_ASS_W30, VIOC_ASS_CAS_PRICE, VIOC_ASS_GS_PRICE] call VIOC_AS_fnc_log;
};

/*
	VIOC_air_support.sqf - agregado por tools/vio_build.py (parche air_support; copia configurada, no es del autor de la
	mision). Fuente: work/v6_build/air_support/.

	Cliente de "PEDIR: Apoyo aereo (A-10 / Ghostrider)": CUALQUIER jugador (no solo el comandante) pide, con SUS fondos,
	  - A-10: aparece, hace una pasada de ataque sobre el punto marcado (canon, cohetes, bombas guiadas o canon + cohetes)
	    y desaparece;
	  - Ghostrider (canonero AC-130J hecho con un C-130J): da circulos alto sobre el blanco y lo ataca con 105 mm y 30 mm
	    durante unos minutos; si lo derriban, el siguiente tarda 30 min (lobby).
	  La accion abre el mapa con un panel a la derecha: A-10 o GHOSTRIDER, tipo de ataque (A-10), clic = blanco (o DONDE
	  MIRO = el punto al que mirabas al usar la accion); el panel muestra avion, blanco, costo, cuando llega, espera del
	  bando y tus fondos; CONFIRMAR manda el pedido al servidor (VIOC_AS_fnc_request en VIOC_air_support_server.sqf),
	  que valida todo otra vez y cobra; la respuesta llega en un aviso. Esc / M / CANCELAR cierra sin pedir nada.
	  Con un Ghostrider tuyo en el aire aparece la accion "GHOSTRIDER: nuevo blanco" (mismo panel: clic dentro del
	  circulo de la orbita). Marcadores solo tuyos: orbita y blanco del Ghostrider, blanco del A-10.
	Solo cliente (hasInterface). Datos del servidor en VIOC_AS_CFG.
	Consola (Ejecucion local): [false] spawn VIOC_ASR_fnc_open;   abre el panel;   VIOC_AS_CFG   datos del servidor;
	    VIOC_ASR_GS   tu Ghostrider activo (objNull si no hay);   VIOC_ASR_ST   ultimo estado recibido del servidor
*/
if (!hasInterface) exitWith {};
if ((missionNamespace getVariable ["VIOC_AIR_SUPPORT", 1]) <= 0) exitWith {};

VIOC_ASR_KIND = "cas";
VIOC_ASR_MODE = 0;
VIOC_ASR_POS = [];
VIOC_ASR_LOOK = [];
VIOC_ASR_OPEN = false;
VIOC_ASR_RE = false;		//--- el panel esta en modo "nuevo blanco" del Ghostrider
VIOC_ASR_CTRLS = [];
VIOC_ASR_INFO = controlNull;
VIOC_ASR_BK = [];			//--- botones A-10 / GHOSTRIDER
VIOC_ASR_BM = [];			//--- botones de tipo de ataque del A-10
VIOC_ASR_ST = [];			//--- estado del servidor: [A-10 activo, espera s, Ghostrider activo, espera s, motivo, tu Ghostrider, centro, blanco]
VIOC_ASR_ST_T = -1e9;		//--- time local en que llego
VIOC_ASR_GS = objNull;		//--- tu Ghostrider activo
VIOC_ASR_GS_C = [];
VIOC_ASR_GS_A = [];
VIOC_ASR_CAS = objNull;
VIOC_ASR_MK = "vioc_asr_t";
VIOC_ASR_MKD = "vioc_asr_td";
VIOC_ASR_MKO = "vioc_asr_to";
VIOC_ASR_GSO = "vioc_asr_gso";
VIOC_ASR_GSA = "vioc_asr_gsa";
VIOC_ASR_CASM = "vioc_asr_cas";

//--- Datos del servidor: [activo, [[A-10 oeste, este], [Ghostrider oeste, este]], nombres, [modos oeste, este], precio A-10,
//--- precio Ghostrider, fuego s, espera A-10 s, espera Ghostrider s, espera derribado s, radio orbita, peligro m, altura, peligro bombas]
VIOC_ASR_fnc_cfg = {missionNamespace getVariable ["VIOC_AS_CFG", []]};
VIOC_ASR_fnc_si = {[west, east] find CTI_P_SideJoined};

//--- Clase del A-10 (0) o del Ghostrider (1) de tu bando ("" si no hay).
VIOC_ASR_fnc_cls = {
	params ["_k"];
	private _cfg = call VIOC_ASR_fnc_cfg;
	private _si = call VIOC_ASR_fnc_si;
	if (_si < 0 || {count _cfg < 14} || {!((_cfg select 0) isEqualTo true)}) exitWith {""};
	private _c = ((_cfg select 1) param [_k, []]) param [_si, ""];
	if !(_c isEqualType "") exitWith {""};
	_c
};
VIOC_ASR_fnc_avail = {(([0] call VIOC_ASR_fnc_cls) != "") || {([1] call VIOC_ASR_fnc_cls) != ""}};
VIOC_ASR_fnc_c = {
	params ["_i", "_def"];
	private _v = (call VIOC_ASR_fnc_cfg) param [_i, _def];
	if !(_v isEqualType _def) then {_v = _def};
	_v
};
VIOC_ASR_fnc_modes = {
	private _si = call VIOC_ASR_fnc_si;
	private _m = ([3, []] call VIOC_ASR_fnc_c) param [_si max 0, []];
	if !(_m isEqualType []) then {_m = []};
	[0, 1, 2, 3] apply {(_m param [_x, false]) isEqualTo true}
};
VIOC_ASR_MODE_NAMES = ["CANON", "COHETES", "BOMBAS GUIADAS", "MIXTO"];
VIOC_ASR_MODE_DESC = ["canon (rafaga de 3 s)", "cohetes", "bombas guiadas por laser (2)", "canon + cohetes"];

//--- Texto seguro para parseText.
VIOC_ASR_fnc_esc = {
	params [["_s", "", [""]]];
	private _o = [];
	{
		switch (_x) do {
			case 38: {_o append (toArray "&amp;")};
			case 60: {_o append (toArray "&lt;")};
			case 62: {_o append (toArray "&gt;")};
			default {_o pushBack _x};
		};
	} forEach (toArray _s);
	toString _o
};
VIOC_ASR_fnc_name = {
	params ["_c"];
	private _n = getText (configFile >> "CfgVehicles" >> _c >> "displayName");
	if (_n == "") then {_n = _c};
	[_n] call VIOC_ASR_fnc_esc
};
VIOC_ASR_fnc_mmss = {
	params ["_s"];
	_s = round (_s max 0);
	private _sec = _s mod 60;
	format ["%1:%2%3", floor (_s / 60), ["", "0"] select (_sec < 10), _sec]
};

//--- Hay tropas propias (o aliadas) a menos de _r de _pos (aviso en el panel; el servidor lo vuelve a mirar).
VIOC_ASR_fnc_friendlyNear = {
	params ["_pos", "_r"];
	private _side = CTI_P_SideJoined;
	(([_pos select 0, _pos select 1, 0] nearEntities [["CAManBase", "LandVehicle", "StaticWeapon", "Ship", "Air"], _r]) findIf {
		alive _x && {
			private _s = if (_x isKindOf "CAManBase") then {side group _x} else {if (({alive _x} count (crew _x)) > 0) then {side _x} else {civilian}};
			(_s in [west, east, resistance]) && {(_side getFriend _s) >= 0.6}
		}
	}) >= 0
};

//--- Estado del bando segun el ultimo dato del servidor: [ocupado, espera s que queda, motivo].
VIOC_ASR_fnc_state = {
	params ["_k"];
	if (count VIOC_ASR_ST < 5) exitWith {[false, 0, ""]};
	private _el = time - VIOC_ASR_ST_T;
	[(VIOC_ASR_ST select (_k * 2)) isEqualTo true, ((VIOC_ASR_ST select (_k * 2 + 1)) - _el) max 0, if (_k == 1) then {VIOC_ASR_ST select 4} else {""}]
};

//--- Rehace el texto del panel.
VIOC_ASR_fnc_refresh = {
	if (isNull VIOC_ASR_INFO) exitWith {};
	private _l = [];
	private _danger = [11, 75] call VIOC_ASR_fnc_c;
	private _R = [10, 1800] call VIOC_ASR_fnc_c;
	if (VIOC_ASR_RE) then {
		_l pushBack format ["<t color='#9fd3ff'>Orbita:</t> circulo azul de %1 m (cuadricula %2)", _R, if (count VIOC_ASR_GS_C > 1) then {mapGridPosition VIOC_ASR_GS_C} else {"?"}];
		_l pushBack format ["<t color='#9fd3ff'>Blanco actual:</t> %1", if (count VIOC_ASR_GS_A > 1) then {format ["cuadricula %1", mapGridPosition VIOC_ASR_GS_A]} else {"?"}];
		if (count VIOC_ASR_POS < 2) then {
			_l pushBack "<t color='#9fd3ff'>Nuevo blanco:</t> <t color='#F5D363'>haz clic dentro del circulo azul (o DONDE MIRO)</t>";
		} else {
			private _d = if (count VIOC_ASR_GS_C > 1) then {VIOC_ASR_POS distance2D VIOC_ASR_GS_C} else {0};
			_l pushBack format ["<t color='#9fd3ff'>Nuevo blanco:</t> cuadricula %1%2", mapGridPosition VIOC_ASR_POS, if (_d > _R) then {format [" <t color='#F56363'>(fuera de la orbita: %1 m del centro)</t>", round _d]} else {""}];
			if ([VIOC_ASR_POS, _danger] call VIOC_ASR_fnc_friendlyNear) then {_l pushBack format ["<t color='#F56363'>Hay tropas propias a menos de %1 m: no disparara ahi mientras sigan.</t>", _danger]};
		};
		if (isNull VIOC_ASR_GS || {!alive VIOC_ASR_GS}) then {_l pushBack "<t color='#F56363'>Ya no tienes un Ghostrider en el aire.</t>"};
		VIOC_ASR_INFO ctrlSetStructuredText parseText format ["<t size='0.85'>%1</t>", _l joinString "<br/>"];
	};
	if (VIOC_ASR_RE) exitWith {};
	private _k = ["cas", "gs"] find VIOC_ASR_KIND;
	private _cls = [_k] call VIOC_ASR_fnc_cls;
	private _price = [[4, 6000] call VIOC_ASR_fnc_c, [5, 12000] call VIOC_ASR_fnc_c] select _k;
	private _funds = call CTI_CL_FNC_GetPlayerFunds;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
	if (_cls == "") then {
		_l pushBack format ["<t color='#F56363'>Tu bando no tiene %1 en este escenario.</t>", ["avion de ataque (A-10)", "canonero (Ghostrider)"] select _k];
	} else {
		if (_k == 0) then {
			_l pushBack format ["<t color='#9fd3ff'>Avion:</t> %1 (una pasada en picado y se va)", [_cls] call VIOC_ASR_fnc_name];
			_l pushBack format ["<t color='#9fd3ff'>Ataque:</t> %1", VIOC_ASR_MODE_DESC select VIOC_ASR_MODE];
		} else {
			_l pushBack format ["<t color='#9fd3ff'>Avion:</t> Ghostrider (%1 con 105 mm y 30 mm)", [_cls] call VIOC_ASR_fnc_name];
			_l pushBack format ["<t color='#9fd3ff'>Orbita:</t> circulo de %1 m a %2 m de altura; fuego %3 min", _R, [12, 2500] call VIOC_ASR_fnc_c, round (([6, 300] call VIOC_ASR_fnc_c) / 60)];
		};
	};
	_l pushBack format ["<t color='#9fd3ff'>Blanco:</t> %1", if (count VIOC_ASR_POS < 2) then {"<t color='#F5D363'>haz clic en el mapa (o DONDE MIRO)</t>"} else {format ["cuadricula %1", mapGridPosition VIOC_ASR_POS]}];
	_l pushBack format ["<t color='#9fd3ff'>Costo:</t> $%1   <t color='#9fd3ff'>Tus fondos:</t> <t color='%3'>$%2</t>", _price, round _funds, if (_funds >= _price) then {"#76F563"} else {"#F56363"}];
	_l pushBack format ["<t color='#9fd3ff'>Llega:</t> %1", ["unos 25 s despues de confirmar", "en 1-2 min"] select _k];
	([_k] call VIOC_ASR_fnc_state) params ["_busy", "_cd", "_why"];
	_l pushBack (switch (true) do {
		case (count VIOC_ASR_ST < 5): {"<t color='#aaaaaa'>Estado: preguntando al mando...</t>"};
		case (_busy): {format ["<t color='#F5D363'>Tu bando ya tiene un %1 en el aire (uno por bando).</t>", ["A-10", "Ghostrider"] select _k]};
		case (_cd > 0): {format ["<t color='#F5D363'>Espera del bando: faltan %1 min%2</t>", [_cd] call VIOC_ASR_fnc_mmss, if (_why == "lost") then {" (el anterior fue derribado)"} else {""}]};
		default {"<t color='#76F563'>Disponible</t>"};
	});
	if (count VIOC_ASR_POS > 1) then {
		private _dg = if (_k == 0 && {VIOC_ASR_MODE == 2}) then {[13, 100] call VIOC_ASR_fnc_c} else {_danger};
		if ([VIOC_ASR_POS, _dg] call VIOC_ASR_fnc_friendlyNear) then {_l pushBack format ["<t color='#F56363'>Hay tropas propias (o tu) a menos de %1 m del blanco: no se puede.</t>", _dg]};
	};
	_l pushBack format ["<t color='#aaaaaa'>%1</t>", if (_k == 0) then {format ["No dispara si hay tropas propias a menos de %1 m del blanco (%2 m con bombas). Espera del bando despues: %3 min.", _danger, [13, 100] call VIOC_ASR_fnc_c, round (([7, 600] call VIOC_ASR_fnc_c) / 60)]} else {format ["Busca enemigos a menos de 150 m del blanco; no dispara a menos de %1 m de tropas propias. Cambia el blanco con la accion GHOSTRIDER: nuevo blanco. Espera despues: %2 min (%3 min si lo derriban).", _danger, round (([8, 900] call VIOC_ASR_fnc_c) / 60), round (([9, 1800] call VIOC_ASR_fnc_c) / 60)]}];
	VIOC_ASR_INFO ctrlSetStructuredText parseText format ["<t size='0.85'>%1</t>", _l joinString "<br/>"];
};

//--- Colores de los botones segun lo elegido y lo disponible.
VIOC_ASR_fnc_paint = {
	private _on = [0.2, 0.45, 0.75, 1];
	private _off = [0.12, 0.12, 0.12, 0.95];
	private _na = [0.3, 0.3, 0.3, 0.5];
	{
		private _ok = ([_forEachIndex] call VIOC_ASR_fnc_cls) != "";
		_x ctrlEnable _ok;
		_x ctrlSetBackgroundColor (if (!_ok) then {_na} else {if ((["cas", "gs"] select _forEachIndex) == VIOC_ASR_KIND) then {_on} else {_off}});
	} forEach VIOC_ASR_BK;
	private _m = call VIOC_ASR_fnc_modes;
	{
		private _ok = _m select _forEachIndex;
		_x ctrlShow (VIOC_ASR_KIND == "cas");
		_x ctrlEnable _ok;
		_x ctrlSetBackgroundColor (if (!_ok) then {_na} else {if (_forEachIndex == VIOC_ASR_MODE) then {_on} else {_off}});
	} forEach VIOC_ASR_BM;
};
VIOC_ASR_fnc_setKind = {
	params ["_k"];
	if ((["cas", "gs"] find _k) < 0 || {([["cas", "gs"] find _k] call VIOC_ASR_fnc_cls) == ""}) exitWith {};
	VIOC_ASR_KIND = _k;
	if (count VIOC_ASR_POS > 1) then {[VIOC_ASR_POS] call VIOC_ASR_fnc_click} else {call VIOC_ASR_fnc_paint; call VIOC_ASR_fnc_refresh};
};
VIOC_ASR_fnc_setMode = {
	params ["_m"];
	if !((call VIOC_ASR_fnc_modes) param [_m, false]) exitWith {};
	VIOC_ASR_MODE = _m;
	if (count VIOC_ASR_POS > 1) then {[VIOC_ASR_POS] call VIOC_ASR_fnc_click} else {call VIOC_ASR_fnc_paint; call VIOC_ASR_fnc_refresh};
};

//--- Clic en el mapa (o DONDE MIRO): blanco + circulos previstos (peligro en rojo, orbita en azul).
VIOC_ASR_fnc_click = {
	params ["_pos"];
	VIOC_ASR_POS = [_pos select 0, _pos select 1, 0];
	deleteMarkerLocal VIOC_ASR_MK;
	deleteMarkerLocal VIOC_ASR_MKD;
	deleteMarkerLocal VIOC_ASR_MKO;
	private _gs = VIOC_ASR_RE || {VIOC_ASR_KIND == "gs"};
	private _dg = if (!_gs && {VIOC_ASR_MODE == 2}) then {[13, 100] call VIOC_ASR_fnc_c} else {[11, 75] call VIOC_ASR_fnc_c};
	private _z = createMarkerLocal [VIOC_ASR_MKD, VIOC_ASR_POS];
	_z setMarkerShapeLocal "ELLIPSE";
	_z setMarkerSizeLocal [_dg, _dg];
	_z setMarkerBrushLocal "Border";
	_z setMarkerColorLocal "ColorRed";
	if (_gs && {!VIOC_ASR_RE}) then {
		private _R = [10, 1800] call VIOC_ASR_fnc_c;
		private _o = createMarkerLocal [VIOC_ASR_MKO, VIOC_ASR_POS];
		_o setMarkerShapeLocal "ELLIPSE";
		_o setMarkerSizeLocal [_R, _R];
		_o setMarkerBrushLocal "Border";
		_o setMarkerColorLocal "ColorBlue";
	};
	private _m = createMarkerLocal [VIOC_ASR_MK, VIOC_ASR_POS];
	_m setMarkerTypeLocal "mil_destroy";
	_m setMarkerColorLocal "ColorRed";
	_m setMarkerTextLocal (if (VIOC_ASR_RE) then {"Nuevo blanco (Ghostrider)"} else {if (_gs) then {"Blanco (Ghostrider)"} else {"Blanco (A-10)"}});
	call VIOC_ASR_fnc_paint;
	call VIOC_ASR_fnc_refresh;
};
VIOC_ASR_fnc_look = {
	if (count VIOC_ASR_LOOK < 2) exitWith {hint "No mirabas a un punto del terreno al usar la accion (mira al blanco y vuelve a usarla), o haz clic en el mapa."};
	[VIOC_ASR_LOOK] call VIOC_ASR_fnc_click;
	mapAnimAdd [0.5, ctrlMapScale ((findDisplay 12) displayCtrl 51), VIOC_ASR_LOOK];
	mapAnimCommit;
};

//--- CONFIRMAR: manda el pedido (o el nuevo blanco) al servidor, que vuelve a validar todo y cobra.
VIOC_ASR_fnc_confirm = {
	if (count VIOC_ASR_POS < 2) exitWith {hint "Haz clic en el mapa para elegir el blanco (o usa DONDE MIRO)."};
	if (VIOC_ASR_RE) exitWith {
		private _R = [10, 1800] call VIOC_ASR_fnc_c;
		switch (true) do {
			case (isNull VIOC_ASR_GS || {!alive VIOC_ASR_GS}): {hint "Ya no tienes un Ghostrider en el aire."};
			case (count VIOC_ASR_GS_C > 1 && {(VIOC_ASR_POS distance2D VIOC_ASR_GS_C) > _R}): {hint format ["El nuevo blanco tiene que estar dentro de la orbita (%1 m del centro).", _R]};
			default {
				[player, VIOC_ASR_POS] remoteExecCall ["VIOC_AS_fnc_retarget", 2];
				systemChat "[Apoyo aereo] Nuevo blanco enviado al Ghostrider...";
				VIOC_ASR_OPEN = false;
				openMap false;
			};
		};
	};
	private _k = ["cas", "gs"] find VIOC_ASR_KIND;
	if (([_k] call VIOC_ASR_fnc_cls) == "") exitWith {hint "Tu bando no tiene ese avion en este escenario."};
	if (_k == 0 && {!((call VIOC_ASR_fnc_modes) select VIOC_ASR_MODE)}) exitWith {hint "Este avion no lleva armas para ese tipo de ataque: elige otro."};
	([_k] call VIOC_ASR_fnc_state) params ["_busy", "_cd"];
	if (_busy) exitWith {hint format ["Tu bando ya tiene un %1 en el aire (uno por bando).", ["A-10", "Ghostrider"] select _k]};
	if (_cd > 0) exitWith {hint format ["Todavia no: faltan %1 min.", [_cd] call VIOC_ASR_fnc_mmss]};
	private _price = [[4, 6000] call VIOC_ASR_fnc_c, [5, 12000] call VIOC_ASR_fnc_c] select _k;
	private _funds = call CTI_CL_FNC_GetPlayerFunds;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
	if (_funds < _price) exitWith {hint format ["No te alcanza: cuesta $%1 y tienes $%2.", _price, round _funds]};
	private _dg = if (_k == 0 && {VIOC_ASR_MODE == 2}) then {[13, 100] call VIOC_ASR_fnc_c} else {[11, 75] call VIOC_ASR_fnc_c};
	if ([VIOC_ASR_POS, _dg] call VIOC_ASR_fnc_friendlyNear) exitWith {hint format ["Hay tropas propias (o tu) a menos de %1 m del blanco: marca un punto mas lejos.", _dg]};
	[player, VIOC_ASR_KIND, VIOC_ASR_POS, VIOC_ASR_MODE, _price] remoteExecCall ["VIOC_AS_fnc_request", 2];
	systemChat "[Apoyo aereo] Pedido enviado al mando...";
	VIOC_ASR_OPEN = false;
	openMap false;
};

//--- Crea el panel sobre el mapa (pantalla 12). Devuelve true si pudo.
VIOC_ASR_fnc_build = {
	params ["_d"];
	VIOC_ASR_CTRLS = [];
	VIOC_ASR_BK = [];
	VIOC_ASR_BM = [];
	private _mk = {
		params ["_cls", "_pos"];
		private _c = _d ctrlCreate [_cls, -1];
		_c ctrlSetPosition _pos;
		_c ctrlCommit 0;
		VIOC_ASR_CTRLS pushBack _c;
		_c
	};
	private _btn = {
		params ["_pos", "_txt", "_code"];
		private _b = ["RscButton", _pos] call _mk;
		_b ctrlSetText _txt;
		_b ctrlAddEventHandler ["ButtonClick", _code];
		_b
	};
	private _W = safeZoneW;
	private _H = safeZoneH;
	private _x0 = safeZoneX + _W * 0.715;
	private _y0 = safeZoneY + _H * 0.08;
	private _w = _W * 0.275;
	private _p = _W * 0.005;
	private _lh = _H * 0.032;
	private _iw = _w - 2 * _p;
	private _b2 = (_iw - _p) / 2;
	private _b3 = (_iw - 2 * _p) / 3;
	private _hInfo = _H * ([0.30, 0.22] select (!VIOC_ASR_RE));
	private _hAll = _p + _lh * 2.6 + (if (VIOC_ASR_RE) then {0} else {(_lh * 1.15 + _p) + 2 * (_lh * 1.05 + _p)}) + _hInfo + _p + _lh * 1.2 + _p;
	private _bg = ["RscText", [_x0, _y0, _w, _hAll]] call _mk;
	if (isNull _bg) exitWith {false};
	_bg ctrlSetBackgroundColor [0, 0, 0, 0.8];
	private _y = _y0 + _p;
	private _t = ["RscStructuredText", [_x0 + _p, _y, _iw, _lh * 2.6]] call _mk;
	_t ctrlSetStructuredText parseText (if (VIOC_ASR_RE) then {
		"<t size='1.05' color='#ffb27f'>GHOSTRIDER: NUEVO BLANCO</t><br/><t size='0.8'>Clic dentro del circulo azul de la orbita (o DONDE MIRO). El Ghostrider sigue dando circulos y dispara al nuevo punto.</t>"
	} else {
		"<t size='1.05' color='#ffb27f'>PEDIR APOYO AEREO</t><br/><t size='0.8'>Elige el avion, el tipo de ataque y haz clic en el blanco. Se paga con TUS fondos.</t>"
	});
	_y = _y + _lh * 2.6;
	if (!VIOC_ASR_RE) then {
		private _n0 = ([0] call VIOC_ASR_fnc_cls);
		VIOC_ASR_BK pushBack ([[_x0 + _p, _y, _b2, _lh * 1.15], if (_n0 == "") then {"A-10"} else {toUpper getText (configFile >> "CfgVehicles" >> _n0 >> "displayName")}, "with missionNamespace do {['cas'] call VIOC_ASR_fnc_setKind}"] call _btn);
		VIOC_ASR_BK pushBack ([[_x0 + _p * 2 + _b2, _y, _b2, _lh * 1.15], "GHOSTRIDER", "with missionNamespace do {['gs'] call VIOC_ASR_fnc_setKind}"] call _btn);
		_y = _y + _lh * 1.15 + _p;
		{
			private _r = floor (_forEachIndex / 2);
			private _c = _forEachIndex mod 2;
			VIOC_ASR_BM pushBack ([[_x0 + _p + _c * (_b2 + _p), _y + _r * (_lh * 1.05 + _p), _b2, _lh * 1.05], _x, format ["with missionNamespace do {[%1] call VIOC_ASR_fnc_setMode}", _forEachIndex]] call _btn);
		} forEach VIOC_ASR_MODE_NAMES;
		_y = _y + 2 * (_lh * 1.05 + _p);
	};
	private _info = ["RscStructuredText", [_x0 + _p, _y, _iw, _hInfo]] call _mk;
	_y = _y + _hInfo + _p;
	[[_x0 + _p, _y, _b3, _lh * 1.2], "DONDE MIRO", "with missionNamespace do {call VIOC_ASR_fnc_look}"] call _btn;
	private _ok = [[_x0 + _p * 2 + _b3, _y, _b3, _lh * 1.2], "CONFIRMAR", "with missionNamespace do {call VIOC_ASR_fnc_confirm}"] call _btn;
	_ok ctrlSetBackgroundColor [0.2, 0.55, 0.25, 1];
	[[_x0 + _p * 3 + _b3 * 2, _y, _b3, _lh * 1.2], "CANCELAR", "with missionNamespace do {VIOC_ASR_OPEN = false; openMap false}"] call _btn;
	VIOC_ASR_INFO = _info;
	true
};

//--- Cierra el panel: borra controles, marcadores del clic y evento del mapa.
VIOC_ASR_fnc_close = {
	if (!isNil "VIOC_ASR_EH") then {removeMissionEventHandler ["MapSingleClick", VIOC_ASR_EH]; VIOC_ASR_EH = nil};
	{if (!isNull _x) then {ctrlDelete _x}} forEach VIOC_ASR_CTRLS;
	VIOC_ASR_CTRLS = [];
	VIOC_ASR_BK = [];
	VIOC_ASR_BM = [];
	VIOC_ASR_INFO = controlNull;
	deleteMarkerLocal VIOC_ASR_MK;
	deleteMarkerLocal VIOC_ASR_MKD;
	deleteMarkerLocal VIOC_ASR_MKO;
	VIOC_ASR_OPEN = false;
};

//--- Accion "PEDIR: Apoyo aereo" ([false]) o "GHOSTRIDER: nuevo blanco" ([true]) (se corre con spawn).
VIOC_ASR_fnc_open = {
	params [["_re", false]];
	if (VIOC_ASR_OPEN) exitWith {};
	if (!alive player) exitWith {};
	if (!_re && {!(call VIOC_ASR_fnc_avail)}) exitWith {hint "Tu bando no tiene apoyo aereo en este escenario."};
	if (_re && {isNull VIOC_ASR_GS || {!alive VIOC_ASR_GS}}) exitWith {hint "No tienes un Ghostrider en el aire."};
	VIOC_ASR_OPEN = true;
	VIOC_ASR_RE = _re;
	VIOC_ASR_POS = [];
	//--- "donde miro": el punto del terreno al centro de la pantalla al usar la accion (hasta 6 km)
	private _lk = screenToWorld [0.5, 0.5];
	VIOC_ASR_LOOK = if ((count _lk > 1) && {(_lk distance2D player) > 5} && {(_lk distance2D player) < 6000}) then {[_lk select 0, _lk select 1, 0]} else {[]};
	if ((["cas", "gs"] find VIOC_ASR_KIND) < 0 || {([["cas", "gs"] find VIOC_ASR_KIND] call VIOC_ASR_fnc_cls) == ""}) then {VIOC_ASR_KIND = if (([0] call VIOC_ASR_fnc_cls) != "") then {"cas"} else {"gs"}};
	private _m = call VIOC_ASR_fnc_modes;
	if !(_m param [VIOC_ASR_MODE, false]) then {VIOC_ASR_MODE = (_m findIf {_x}) max 0};
	[player] remoteExecCall ["VIOC_AS_fnc_query", 2];
	openMap [true, false];
	private _t = diag_tickTime + 3;
	waitUntil {sleep 0.05; visibleMap || {diag_tickTime > _t}};
	private _d = findDisplay 12;
	if (!visibleMap || {isNull _d} || {!([_d] call VIOC_ASR_fnc_build)}) exitWith {
		call VIOC_ASR_fnc_close;
		hint "No se pudo abrir el panel del mapa. Prueba otra vez con el mapa cerrado.";
	};
	VIOC_ASR_EH = addMissionEventHandler ["MapSingleClick", {
		params ["", "_pos"];
		[_pos] call VIOC_ASR_fnc_click;
	}];
	call VIOC_ASR_fnc_paint;
	call VIOC_ASR_fnc_refresh;
	private _next = diag_tickTime + 1;
	private _q = diag_tickTime + 10;
	waitUntil {
		sleep 0.1;
		if (diag_tickTime > _next) then {_next = diag_tickTime + 1; call VIOC_ASR_fnc_refresh};
		if (diag_tickTime > _q) then {_q = diag_tickTime + 10; [player] remoteExecCall ["VIOC_AS_fnc_query", 2]};
		!visibleMap || {!alive player} || {!VIOC_ASR_OPEN}
	};
	call VIOC_ASR_fnc_close;
	if (visibleMap) then {openMap false};
};

//--- Marcadores (solo tuyos) del Ghostrider activo: orbita y blanco.
VIOC_ASR_fnc_gsMarks = {
	deleteMarkerLocal VIOC_ASR_GSO;
	deleteMarkerLocal VIOC_ASR_GSA;
	if (count VIOC_ASR_GS_C < 2) exitWith {};
	private _R = [10, 1800] call VIOC_ASR_fnc_c;
	private _o = createMarkerLocal [VIOC_ASR_GSO, VIOC_ASR_GS_C];
	_o setMarkerShapeLocal "ELLIPSE";
	_o setMarkerSizeLocal [_R, _R];
	_o setMarkerBrushLocal "Border";
	_o setMarkerColorLocal "ColorBlue";
	if (count VIOC_ASR_GS_A > 1) then {
		private _a = createMarkerLocal [VIOC_ASR_GSA, VIOC_ASR_GS_A];
		_a setMarkerTypeLocal "mil_destroy";
		_a setMarkerColorLocal "ColorRed";
		_a setMarkerTextLocal "Ghostrider: blanco";
	};
};

//--- Busca el avion por su marca si todavia no llego por la red.
VIOC_ASR_fnc_find = {
	params ["_kind"];
	private _uid = getPlayerUID player;
	if (_uid == "") then {_uid = "local"};
	private _v = objNull;
	private _t = time + 15;
	waitUntil {
		sleep 0.5;
		_v = (vehicles select {((_x getVariable ["vioc_as_uid", ""]) == _uid) && {(_x getVariable ["vioc_as_kind", ""]) == _kind} && {alive _x}}) param [0, objNull];
		!isNull _v || {time > _t}
	};
	_v
};

//--- Respuesta del servidor (VIOC_AS_fnc_reply). _data: ["cas", avion, blanco, espera] / ["gs", avion, centro, radio] / ["re", avion, centro, radio, blanco].
VIOC_ASR_fnc_reply = {
	params ["_ok", "_text", ["_data", []]];
	private _txt = [_text] call VIOC_ASR_fnc_esc;
	systemChat format ["[Apoyo aereo] %1", _text];
	if (!_ok) exitWith {
		hint parseText format ["<t size='1.1' color='#F56363'>Apoyo aereo: no se pudo</t><br/><br/><t align='left'>%1</t>", _txt];
	};
	_data params [["_kind", ""], ["_pl", objNull], ["_c", []]];
	VIOC_ASR_ST = [];	//--- el estado cambio: se vuelve a preguntar al abrir el panel
	switch (_kind) do {
		case "cas": {
			VIOC_ASR_CAS = _pl;
			deleteMarkerLocal VIOC_ASR_CASM;
			if (count _c > 1) then {
				private _m = createMarkerLocal [VIOC_ASR_CASM, _c];
				_m setMarkerTypeLocal "mil_destroy";
				_m setMarkerColorLocal "ColorRed";
				_m setMarkerTextLocal "A-10: blanco";
			};
			hint parseText format ["<t size='1.1' color='#76F563'>Apoyo aereo: A-10</t><br/><br/><t align='left'>%1</t>", _txt];
		};
		case "gs": {
			VIOC_ASR_GS_C = _c;
			VIOC_ASR_GS_A = _c;
			call VIOC_ASR_fnc_gsMarks;
			hint parseText format ["<t size='1.1' color='#76F563'>Apoyo aereo: Ghostrider</t><br/><br/><t align='left'>%1<br/><br/>Para cambiar el blanco: accion 'GHOSTRIDER: nuevo blanco' (rueda del raton), clic dentro del circulo azul. No dispara a menos de %2 m de tropas propias.</t>", _txt, [11, 75] call VIOC_ASR_fnc_c];
			if (isNull _pl) then {
				[] spawn {
					private _v = ["gs"] call VIOC_ASR_fnc_find;
					if (!isNull _v) then {VIOC_ASR_GS = _v};
				};
			} else {VIOC_ASR_GS = _pl};
		};
		case "re": {
			_data params ["", "", "", "", ["_a", []]];
			if (count _a > 1) then {VIOC_ASR_GS_A = _a};
			if (count _c > 1) then {VIOC_ASR_GS_C = _c};
			call VIOC_ASR_fnc_gsMarks;
			hint parseText format ["<t size='1.1' color='#76F563'>Ghostrider</t><br/><br/><t align='left'>%1</t>", _txt];
		};
		default {hint _text};
	};
};

//--- Aviso del servidor. _data = [tipo, espera s] cuando termina tu A-10 o tu Ghostrider.
VIOC_ASR_fnc_note = {
	params [["_text", "", [""]], ["_data", []]];
	systemChat format ["[Apoyo aereo] %1", _text];
	hint _text;
	if (count _data < 2) exitWith {};
	VIOC_ASR_ST = [];
	if ((_data select 0) == "cas") then {
		VIOC_ASR_CAS = objNull;
		deleteMarkerLocal VIOC_ASR_CASM;
	} else {
		VIOC_ASR_GS = objNull;
		VIOC_ASR_GS_C = [];
		VIOC_ASR_GS_A = [];
		call VIOC_ASR_fnc_gsMarks;
	};
};

//--- Estado del bando (respuesta a VIOC_AS_fnc_query).
VIOC_ASR_fnc_status = {
	params [["_st", []]];
	if !(_st isEqualType []) exitWith {};
	VIOC_ASR_ST = _st;
	VIOC_ASR_ST_T = time;
	private _mine = _st param [5, objNull];
	if (!isNull _mine && {alive _mine}) then {
		VIOC_ASR_GS = _mine;
		private _c = _st param [6, []];
		private _a = _st param [7, []];
		if ((count _c > 1) && {!(_c isEqualTo VIOC_ASR_GS_C) || {!(_a isEqualTo VIOC_ASR_GS_A)}}) then {
			VIOC_ASR_GS_C = _c;
			VIOC_ASR_GS_A = _a;
			call VIOC_ASR_fnc_gsMarks;
		};
	};
	call VIOC_ASR_fnc_refresh;
};

